window.IV=window.IV||{};IV.univ=IV.univ||{};IV.univ["u003"]={"univ":"가천대학교","reviews":[{"univ":"가천대학교","dept":"건축학부","jeonhyeong":"학생부교과(지역균형전형)","method":"","notes":"","qa":[{"q":"지원동기를 말씀해주십시오.","a":"가천대학교 커리큘럼에서 다른 학교들과는 달리 봉사활동이 필수 교양 강의인 것을 보았습니다. 평소 봉사정신과 책임감이 뛰어난 저는 이를 보고 가천대학교와 제가 정말 잘 맞을 것 같다는 생각이 들어 지원하게 되었습니다. 또, 고등학교 1학년 교내체험으로 인문과 공학의 융합점인 건축의 매력을 깨닫게 되어 건축학부에 지원하게 되었습니다."},{"q":"롤모델이 있습니까?","a":""},{"q":"좋아하는 건축물이 있습니까?","a":""},{"q":"마지막으로 하실 말씀 있으십니까?","a":"제가 면접을 보러 간다고 했을 때 저희 학교 선생님께서 이렇게 말씀하셨습니다. “야, 너를 뽑지 않는다는 것은 그 학교가 자기 눈을 찌르는 것과 같다.” 하하하하(같이웃음)저를 꼭 뽑아주시면 감사하겠습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"경영학과","jeonhyeong":"학생부종합(가천바람개비전형)","method":"면접시간 10분 간 질의응답","notes":"","qa":[{"q":"동아리 활동에서 카드사 관련 조사활동을 했던데 어떤 활동을 하셨나요?","a":"코로나 당시 카드사들의 활동과 좋은 실적을 보인 카드사와 실적이 안 좋았던 카드사와의 차별점을 알아보았다. 실적이 좋았던 카드사의 경우 MZ세대를 저격한 온라인 마케팅을 활용하여 좋은 실적을 낼 수 있었다."},{"q":"기업을 운영하며 가장 중요하다고 생각하는 것은 무엇인가요?","a":"기업 지배구조의 투명성이라고 생각한다."},{"q":"기업 지배구조의 투명성이 왜 중요하다고 생각하나요?","a":"대답 못 함."},{"q":"동아리 활동에서 애자일 경영, 헬릭스 경영 등에 대해서 배웠다고 돼 있는데, 애자일 경영이 무엇인가요?","a":"급변하는 시장 환경 속에서 다양한 수요에 유연하고 민첩하게 대응하기 위해 필요한 경영 방식이다."},{"q":"학교에서 많은 활동들을 했던데 학업에 지장이 가진 않았나요?","a":"고등학교에서만 할 수 있는 다양한 활동들을 하는 것 또한 가치 있다고 생각하고 무엇보다 경험을 중요하게 생각했다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"반도체대학","jeonhyeong":"학생부종합(농어촌종합전형)","method":"3대 1/ 약 10분 면접 , 생기부 기반 면접","notes":"대기시간에 전자기기를 사용할 수 없음(학생부 자료 볼 수 있음)지정된 입 출입구가 있어 잘 찾아서 가야함","qa":[{"q":"지원동기","a":"저는 반도체 연구원이라는 꿈을 가지고 반도체 대학에 지원하게 된 면접번호입니다. 저는 고교시절 태양전지실험, 커패시터 특성 실험 등 다수의 전기전자 실험을 하며 꿈에 대학 열망과 흥미를 키웠습니다. 가천대학교의 전 공정과정을 교수님께 배우고 판교밸리와의 협업을 통해 기업이 필요로 하는 인재로 성장할수 있을 것 같아 지원하게 되었습니다."},{"q":"물리학1 시간에 8대공정에 대해 활동을 했는데 8대공정이 무엇인지 설명하시오.","a":"8대 공정은 반도체 생산 과정의 주요 8가지 과정입니다"},{"q":"인상깊은 공정 하나만 이야기 해봐라.","a":"포토공정이 인상깊었습니다. 포토공정은 웨이퍼에 감광액을 활용하여 빛을 통해 회로를 그려 내는 과정입니다."},{"q":"거기서 쓰는 빛에 대해서 알고 있나?","a":"지금 긴장을 해서 잘 기억이 나지 않도록 하겠습니다. 겨울방학에 보완하여 이후 공부에 차질이 없도록 하겠습니다"},{"q":"진로활동에서 커패시터 특성실험을 어떻게 하게 되었나?","a":"물리학 교과서에서 커패시터 특성, 원리에 흥미를 느끼고 탐구하게 되었습니다."},{"q":"진로활동에서 보고서를 제출한 것은 혼자한 것 인가요?","a":"네 보고서는 혼자한 것이고 이후 개 세특에 적힌 것은 같이 한 것입니다."},{"q":"개세특에 적힌 협업 프로젝트에서 역할분배에 어떻게 본인이 역할 하였는지?","a":"저는 팀장은 아니여서 역할을 분배하지는 않았고 자원하여 시뮬레이션을 하는 역할과 재실험하는 역할을 자원하였고 제 역할 뿐만 아니라 알엘 알씨회로 연결을 어려워하는 한 친구가 있었는데 자원하여 도와주었습니다."},{"q":"실험과정에서 어떤 어려움이 있었는지 구체적으로 말해보세요.","a":"함수발생기에서 나와 오실로스코프에서 나오는 파형을 측정하였는데 입력한 주파수 값과 진폭이 다르다는 어려움을 겪었습니다. 함수발생기의 내부저항 때문이라는 것을 알게 되었고 이를 통해 실험 기준 주파수를 낮추어 실험을 진행하였습니다."},{"q":"미적분에서 자이로스코프, 자이로 센서에 대해 탐구하였는데 이에 대해 설명해보시오.","a":"자이로스토프는 3개의 원형 모양고리를 연결하여 어느 방향으로 힘을 가해도 넘어지지 않도록 한 장치입니다. 자이로 센서는 자이로 스코프에 힘에 의해 방향 변화를 감지하고 이를 전기신호로 바꾸는 장치를 추가한 것입니다."},{"q":"자이로 센서 실생활 이용사례?","a":"드론, vr등이 있습니다. 드론은 이륙하는 과정에서 공기저항에 균형을 잡기 위해 사용되고 vr은 방향에 따른 사물을 구현하는 등의 역할을 위해 사용됩니다."},{"q":"1학년때 빙판길 관련한 활동을 하였는데 이과정에 대해 자세히 설명해보세요.","a":"자동차의 바퀴에 얼음 방지 아이젠을 보고 그와 비슷한 소재를 찾아 보았던 것 같습니다. 오래전 기억이라 기억이 잘 나지 않지만 비슷한 과정을 통해 탐구한 것 같습니다"},{"q":"마지막으로 하고 싶은 말","a":"저는 반도체의 속도와 효율을 높여 사람들을 편리하게 해주고 공정과정에의 환경문제를 해결하는 엔지니어가 되고 싶습니다. 가천대학교에서 반도체 공정에 대해 배운다면 실력있는 엔지니어가 될 것이라고 확신 합니다. 부족한 제 답변 들어주셔서 감사합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"반도체대학","jeonhyeong":"학생부종합(기회균형전형)","method":"3대 1 대면면접","notes":"(꼬리질문 - 정류작용이 뭐죠?)편안한 분위기였고, 인성 비중이 높아 인성+전공적합성을 드러낼 수 있는 동아리 활동 중요하다고 느꼈다고 함.","qa":[{"q":"반도체대학 지원 동기가 무엇인가요?","a":"(꼬리질문 있음)"},{"q":"미적분에서 RC, RL회로에 대해서 탐구했는데, RL회로가 뭔가요?","a":""},{"q":"3학년 동아리 활동에서 웨어러블 기기를 주제로 택한 이유가 무엇인가요?","a":""},{"q":"2학년 때 쓰러진 친구를 응급처치했다고 했는데, 어떻게 도왔나요?","a":""},{"q":"동아리장을 맡으면 힘들텐데, 왜 하였나요?","a":""},{"q":"물리학I에서 pn접합으로 이루어진 다이오드를 탐구했는데, 이게 뭐죠?","a":""}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"반도체물리학과","jeonhyeong":"학생부교과(지역균형전형)","method":"생기부기반 면접","notes":"","qa":[{"q":"먼저 자기소개와 본교에 지원하게 된 이유를 말해주세요.","a":"저는 00번 수험생입니다. 저는 중학교에서 물리학에 관심을 가지게 되어서 그이후 물리학을 전공하고 더욱 높은 수준에서 공부하고자 하였습니다. 이 학교가 제가 선택할 수 있는 조건중 가장 좋은 조건인 것 같아 본교에 지원하게 되었습니다."},{"q":"진로 적합성에 대해 질문을 할건데요, 뉴턴의 운동법칙을 이야기하고 설명해 주세요.","a":"뉴턴의 운동법칙은 3가지 인데요. 제1법칙은 관성의 법칙으로 외력이 작용하지 않는 경우 물체가 운동상태를 유지하려는 성질을 가진다는 내용의 법칙입니다. 제2법칙은 가속도의 법칙으로 가속도와 질량을 곱해 물체에 작용하는 알짜힘을 규할수 있는 법칙이라고 알고 있습니다. 마지막으로 제3법칙 작용반작용의 법칙은 물체에 작용하는 힘은 언제나 상호작용력이라는 내용을 가진 법칙이라고 알고 있습니다"},{"q":"블랙홀에 대해 관심이 많으신거 같은데 중력렌즈 효과에 대해 설명해주실 수 있나요?","a":"네, 블랙홀은 매우 큰 질량을 가진 천체로 일반 상대성이론에 의해서 주변의 시공간을 구부립니다. 이때 뒤에 항성과 같은 빛을 내뿜는 천체가 있을 경우 내뿜는 빛이 중력장에 의해 구부러진면서 천체의 형상이 왜곡되는 것을 말합니다"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"생명과학과","jeonhyeong":"학생부종합(농어촌종합전형)","method":"3:1 면접 형식. 큰 테이블에 면접관 3분 앉아계셨고 면접자 전용 책상과 의자 있었음 면접실 옆 대기실에서 유의사항 안내, 대기 및 감독 지도 후 입장기회균형 면접자들과 함께 진행 (7명 대기)","notes":"꼭 합격해서 혁신의 바람을 일으키는 가천인이 되고 싶습니다. 감사합니다.자기소개시 이름 언급 안됨마지막 순서 대기시간 약 1시간","qa":[{"q":"지원동기 말씀해주세요.","a":"안녕하세요, 저는 저의 무한한 잠재력과 창의력, 분석력을 토대로 면역학에 대해 연구하며 리보솜을 이용한 새로운 면역체계를 연구하길 희망하는 지원자 (번호)입니다.고교때 면역학에 관심을 갖고 암세포에 대해 탐구하던 중 리보솜이 암세포의 촉진을 돕는다는 기사를 보고 기사 내용에 기반해 CAR-T 치료와 리보솜의 기능을 접목시킨다면 암의 촉진을 막을 수 있을 것이라 생각했습니다. 최근 면역항암제, 표적 항암제 등 많은 연구가 이루어지고 있는데 저 또한 그러한 연구에 동참해 암을 정복할 수 있는 연구결과를 마주할 날을 앞당길 인재가 되고 싶습니다."},{"q":"행동발달특성에 성실하고 근면하다고 나와있는데 좋은 영향력을 가지고 있는것으로 보여요. 본인의 이러한 점이 어떤 부분에서 드러났는지 말씀해주세요.","a":"저는 동료들에게 신뢰감을 준다는 것에서 드러난다고 생각합니다. 팀 과제를 할때 방황하는 학생에게 위로를 해주고 자신감을 불어넣어주며 신뢰를 형성하고 그에 따라 과제를 성공적으로 마칠 수 있게 하였습니다."},{"q":"지원동기에서 암세포를 연구하고 싶다고 했는데 암세포가 뭔가요? 특징 설명해주세요.","a":"암세포는 사멸해야 하는 세포가 돌연변이의 이유로 공격성과 과다증식성을 나타냅니다. 혈관을 만들어 여러 기관에 퍼져 종양을 생성하는 세포를 말합니다."},{"q":"지원동기에서 언급했던 CAR -T 치료제가 뭔가요?","a":"CAR-T 치료제는 우리 몸에 있는 T세포가 암세포를 잘 인식하지 못한다는 것에서 기반합니다. T세포에 있는 유전정보에 암세포를 구별할 수 있는 유전정보를 이식해 스스로 암을 극복할 수 있게하는 치료법입니다."},{"q":"졸업후 무엇을 하고싶은가요?","a":"가천대학교에는 암당뇨 연구원이 따로 설립되어있다고 알고 있습니다. 저는 졸업 후에 그 연구소에서 앞서 말했던 암을 치료하기 위한 면역체계를 연구하는 연구원이 되고 싶습니다."},{"q":"상염색체가 무엇인가요?","a":"여자와 남자 모두 동일하게 44개씩 가지고 있는 염색체입니다."},{"q":"생명과학2에서 배웠던 전사가 무엇인지 설명해줄래요?","a":"전사는 DNA에서 RNA를 추출해내는 과정입니다."},{"q":"그럼 번역은 무엇인가요?","a":"번역은 RNA가 리보솜의 대단위체와 소단위체와 결합해 단백질을 합성하는 과정입니다."},{"q":"화학2에서 삼투압에 대해 배웠는데 삼투압이 무엇인가요?","a":"삼투압은 수분이나 외부 요인에 따라 체내 수분량을 조절하는 것입니다."},{"q":"동아리 활동때 대기중 오염물질을 측정하는 프로그램을 만들었는데 설명해주세요.","a":"저희는 오렌지프로그램을 이용하였는데 오렌지 프로그램이란 기존에 있던 코딩을 직접 쓰는 것이 아닌 정형화 되어있는 코딩을 조립해 새롭게 만드는 프로그램입니다.오렌지 프로그램의 혼돈 메트릭스를 사용해 대기중 유해물질의 정당성과 정확성을 파악하는 프로그램을 만들었습니다."},{"q":"그 프로그램을 만들며 힘들었던 점이나 본인이 했던 역할","a":"저는 조장을 맡아 다른 대학에 가서 오렌지 프로그램의 사용법을 배워왔습니다. 아무래도 오렌지 프로그램이 생소하다보니 친구들에게 설명하는 것이 어려웠는데 함께 강의를 들었던 친구들이 도와주었고 저도 적극적으로 배우려고 노력해 해결할 수 있었습니다."},{"q":"마지막으로 하고 싶은 말","a":"매 순간이 선택의 연속인 삶속에서 가천대학교 생명과학과 면접을 본 것은 너무나 영광스러웠습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"시스템반도체학과","jeonhyeong":"학생부종합(가천바람개비전형)","method":"3대 1 면접, 10분 이내, 8~10개 정도 질문긴장 풀어주는 질문 해주실 줄 알았는데 안해주심","notes":"시사질문X, 독서활동 관련질문 많이 나올 줄 알았는데 하나도 안나옴. 혹시 모르니 다 준비해가는 게 좋을 듯, 2학년 세특에서만 질문 나왔는데 사람마다 다 다른 듯. 이것도 혹시 모르니 다 준비해가는 게 좋을 듯.","qa":[{"q":"이 학과를 지원하게 된 동기를 말해주세요.","a":"안녕하십니까, 무한한 가능성을 지닌 가번호 00번입니다. 저는 게임을 할 때나 영상을 볼 때 화질을 정말 중요시 해 왔습니다. 이를 통해 CPU와 같은 반도체가 영향을 미친다는 것을 알게 되었습니다. 그 결과 반도체에 대한 관심이 커졌습니다. 특히 반도체 기술이 발전하면서 화질이 향상되는 것을 보며 이 분야의 혁신이 얼마나 중요한지를 깨달았습니다. 저는 가천대학교 시스템 반도체학과에서 이라한 열정을 더욱 발전시켜 미래 반도체 공정 기술을 선도하는 엔지니어가 되고싶어 지원하게 되었습니다."},{"q":"베이즈 정리에 대해 설명해 주세요.","a":"베이즈 정리란 사전 확률을 기반으로 새로운 데이터를 반영하여 사후 확률을 계산하는 통계적 원리입니다."},{"q":"전기회로에서 로그함수가 어떻게 이용되나요?","a":"저는 데시벨에 사용되는 로그함수를 찾아보았습니다. 데시벨에서 로그함수는 사용로그를 사용하여 신호의 비율을 효과적으로 표현하고, 복잡한 계산을 직관적으로 이해할 수 있도록 도와줍니다."},{"q":"레이저 다이오드와 발광다이오드의 차이점에 대해 설명해주세요.","a":"발광다이오드에서 나오는 빛은 여러 파장과 위상의 빛이 혼합되어 있으며, 빛을 특정 방향으로 방출하지 않고 모든방향으로 방출합니다, 반면 레이저 다이오드의 경우 하나의 특정한 파장을 가지는 빛 파동들이 동일한 위상을 가지고, 동일한 방향으로 방출된다는 차이점을 가지고 있습니다."},{"q":"갈륨비소 반도체와 일반 반도체에 대해 어떤걸 조사하셨나요?","a":"저는 이 둘의 차이점에 대해 조사하였습니다. 갈륨비소는 실리콘에 비해 전자 이동성이 높아(기억안나서 대답 못함)+특징에 대해 조사하셨나요?네, 특징에 대해 조사했었습니다"},{"q":"이중 슬릿을 통한 간섭 실험에서 무얼 하였나요?","a":"어두운 공간에서 이중슬릿에 레이저를 쏴 파장의 간격을 직접 측정하였습니다. +무엇을 알게 되었나요?이 부분은 더 공부해오도록 하겠습니다."},{"q":"니크롬선 길이에 따른 전기전도도 측정 실험에서 어떤걸 알게 되었나요?","a":"이 실험을 통해 니크롬선 길이가 변하여도 비저항은 변하지 않는 다는 것을 알게 되었습니다. 그 이유는 비저항은 물질 고유의 특성이기 때문입니다. 온도와 같은 외부요인이 변하지 않는 한 비정항이 변하지 않습니다.+비저항을 어떻게 구하죠?이 부분은 더 공부해오겠습니다."},{"q":"마지막으로 하고 싶은 말 있으신가요?","a":"저는 어려운 도전도 끝까지 해내는 사람입니다. 가천대학교 시스템 반도체학과에서 배움을 행동으로 옮기며 학교를 대표하는 인재로 성장하고 싶습니다. 기회를 주신다면 그 기회를 뛰어넘는 모습으로 꼭 보답하겠습니다. 감사합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"응용통계계학과","jeonhyeong":"학생부교과(지역균형전형)","method":"서류 기반, 면접관 3명, 2단계, 면접 10분","notes":"1. 지원동기 너무 길면 말 자르실 수 있음2. 꼬리 물기 심해서 생활기록부에 나온 개념 다 익혀가야 함","qa":[{"q":"지원동기","a":"저는 가천대로 인하여 다시 태어난 사람입니다 제가 뭘 좋아하는지 뭘 잘하는지 알지 못하였는데 어느날 가천대 총장님의 인터뷰를 본 적이 있었습니다. 총장님께서는 바람개비는 빨리 달려라 잘 돈다 가만히 있으면 돌지 않는다 그러니 바람이 불지 않으면 바람을 일으켜야 한다고 말씀하셨는데요. 저는 그 말이 인상깊었습니다. 저도 직접 나의 꿈을 찾고 직접 바람을 일으켜야겠다고 다짐한 계기였습니다. 그런 가천대에 너무나도 오고 싶어 수시 모집 요강을 살펴본 후 지역 균형을 지원하게 됐습니다. 그 계기가 바로 통계였는데요. 의사결정을 함에 있어서 합리적이고 효율적인 선택을 할 수 있게 해주었습니다. 능통과 과목에는 범주형 자료 분석 다변량 자료 분석 금융 빅데이터 의료 정보 데이터분석 등 제가 흥미 있어 하는 것들이 많았고 수학도 전 과목 다 들을 정도로 좋아해서 응통과는 저에게 배움이 설레는 학과입니다."},{"q":"미분 가능한 함수의 특징","a":"연속해야 합니다."},{"q":"함수가 어떨 때 불연속적이죠?","a":"뾰족하거나(손으로 그래프를 그리며) 이렇게 연속하지 않아서 뚫려있는 함수는 불연속입니다."},{"q":"그 불연속 그래프는 어떻게 적분하죠?","a":"뚫린 곳을 두고 구간을 나누어 적분합니다."},{"q":"확률과 통계 시간에 몬티홀문제로 발표하셨네요. 친구들 반응은 어땠나요.","a":"확률이 50대 50 아니냐는 친구도 있었고 무작위 아니냐는 친구도 있었습니다. 모두가 정답이라 한번 생각해 즐겁게 토론한 경험입니다."},{"q":"본인의 생각은??","a":"저는 선택을 바꾸는 게 맞다고 생각합니다. 그래야 확률이 올라갑니다."},{"q":"시간이 없어서 몬티홀에 대해 더 물어보고 싶은데 못 물어보겠네요. 마지막 할 말씀하세요.","a":"간절히도 가천대에 오고 싶습니다. 가천대는 2012년부터 아주 비약적인 성장을 해온 거로 알고 있습니다. 저도 그 성장에 발맞추어 성장하는 학생이 되고 싶습니다. 감사합니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"의공학과","jeonhyeong":"학생부종합(가천바람개비전형)","method":"생기부 기반 면접","notes":"블라인드 면접 범위는 완전 랜덤 100% 운","qa":[{"q":"의공학과를 희망하게 된 이유","a":"저와 같이 일상생활에 불편함을 가지고 살아가시는 사람들을 위한 의료기기를 만들자라는 목표를 이루기 위해 기초지식을 쌓고자 지원하게 되었습니다."},{"q":"MRI에 대해 알고 있는 것","a":"사람의 인체 내부를 찍어 사람의 내부 질병이나 원인을 찾을 수 있게 해줍니다."},{"q":"홍보부 활동을 하면서 힘들었던 일","a":"우선 저는 전 홍보부원이 홍보를 못했다고 생각을 해서 제가 하면 잘할 것 같아 홍보부에 지원하게 되었습니다. 홍보부에서 처음으로 sns를 통해 홍보 활동을 시작해서 sns를 통한 홍보를 하는데 많은 어려움이 있었습니다. 스토리 및 게시물 양식을 만드는 데에도 어려움이 있었습니다. 그래서 저는 매주 홍보부원들과 어떻게 하면 홍보를 보다 잘 할 수 있는지 회의를 했고 도서관에서 sns 홍보 관련 책도 읽었습니다.또, 다른 학교 홍보부원에게 sns 홍보 관련 조언을 구해서 저만의 sns 양식을 만들었습니다."},{"q":"마지막으로 하고 싶은 말","a":"마지막으로 저는 저의 학업계획에 대해 말씀드리겠습니다.우선 저는 의료공학과 경력개발 로드맵에 있는 의료기기 연구/개발/유지보수 관련으로 공부를 할 계획입니다. 그리고 1,2학년때에는 의공학과 졸업선배 컨설팅 프로그램에 참여해 앞선 선배님들이 겪었던 고충이나 의공학에 대한 팁들을 배워보는 시간을 가질 것입니다. 또, 진로 설계와 경력개발 프로그램에 참여해 제 목표를 이룰 수 있도록 과정들을 상세히 구상해보는 시간도 가질 것입니다. 3학년 1학기에 갈 가천하와이 프리미엄 코스를 위해 틈틈이 토익공부도 할 예정입니다. 가천하와이 프리미엄 코스에 갔다 온 이후 가천 IPP 공동훈련센터에서 운영하는 IPP 장기훈련실습에 참여해서 실전 경험도 가질 예정입니다. 이후에는 독일에 있는 지멘스라는 회사에서 학부연구원으로 가기 위한 공부를 할 예정입니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"자유전공학부","jeonhyeong":"학생부교과(지역균형전형)","method":"면접관 3명과 학생 한명이서 약 10분 간 면접 진행함","notes":"대답을 할 때 면접님들이 자주 웃어주며 반응해주어서 긴장감이 줄어들었습니다.계속해서 미소를 유지하려 의식하였고 면접관님들의 눈을 보며 이야기 하였던 점이 긍정적인 분위기를 만드는데 큰 도움이 되었던 것 같습니다.","qa":[{"q":"본교에 입학하고 나서 구체적인 학업계획을 말해주세요.","a":"우선 저는 1학년때 본교에 입학하여 전공 탐색 세미나를 통해 다양한 전공을 탐색하며 심도있게 저의 전공을 탐색하고 싶습니다. 또한 2학년에 진학하여 미디어커뮤니케이션학과에 진학하여 사회적으로 어려움을 겪고 있는 분들의 진실을 알리는 기자가 되기 위해 역량을 키워 나갈 것입니다. 또한 교내 활동 뿐만 아니라 경기도에서 진행하는 경기도 기회기자단 프로그램에 대학생기자단으로 참가하여 경기도 내에선 어떠한 사회적 약자 계층이 존재하는지, 이를 해결하기 위해 지자체는 어떠한 노력을 해야하는지에 대해 기사를 작성하여 저의 꿈을 실현시키기 위해 노력하려고 합니다."},{"q":"그러면 학생은 미디어커뮤니케이션학과에 진학해 기자가 되는 것이 꿈입니까?","a":"네 그렇습니다."},{"q":"경제수학시간에 생활물가지수와 소비자물가지수의 차이점에 대해 설명해주세요.","a":"생활물가지수는 국민들이 일상생활을 살아갈 때 생필품과 같이 생활에 꼭 필요한 품목들을 대상으로 조사한 지표입니다. 때문에 생활물가지수는 생활에 밀접하게 연관되어 있는 경제 지표입니다. 반면, 후자의 경우에는 생필품뿐만 아니라 의류, 교육비 등 사회 전반에 존재하는 물건 혹은 소비들에 대해서 나타내는 지표입니다. 때문에 전자와 달리 사회의 전체적인 물가를 나타내는 역할을 합니다."},{"q":"그러면 빅맥지수라는 것도 탐구하였는데 빅맥지수는 무엇인가요?","a":"빅맥지수는 현재 세계에서 가장 대중적인 프렌차이즈 기업 중 하나인 맥도날드에서 가장 대표적인 메뉴인 빅맥을 활용하여 각 나라 별 경제력을 측정해보는 지표입니다. 이러한 빅맥지수는 대게 물가가 높은 지역에서는 빅맥의 가격이 높게 형성되며, 물가가 낮은 지역에서는 빅맥의 가격이 낮게 형성된다는 점을 근거로 하여 각국의 물가를 측정해보는 방법입니다."},{"q":"기억나지 않음","a":"기억나지 않음"},{"q":"칸트와 밀의 사상을 비교하여 설명해줄 수 있나요?","a":"죄송합니다. 칸트와 밀과 관련한 부분에선 개념이 부족한 것 같습니다. 하지만 본교에 입학하기 전까지 이러한 부족한 개념에 대한 공부를 하며 가천대가 지향하는 인재상에 걸맞게 학습하여 보완하여 오도록 하겠습니다."},{"q":"그러면 순자의 성악설에 대해서 설명해주세요.","a":"순자는 인간의 본성이 본래 악하게 태어난다고 하였습니다. 하지만 순자는 인간이 악한 본성을 가지고 태어났지만 교육을 통해서 인간인 선한 행동을 할 수 있다고 말하였으며 후천적인 노력을 통해 인간의 악한 본성을 가릴 수 있다고 말하였습니다."},{"q":"뉴미디어 뉴스에서 악플의 문제가 심각하다 하였는데 사례는 무엇이 있습니까?","a":"우선 현재 미디어는 TV, 라디오와 같이 전통적인 매체를 탈피하여 SNS, 유튜브 등 뉴미디어 플랫폼으로 옮겨 가고 있는 상황입니다. 이때 뉴미디어의 대표적인 특성 중 하나인 빠른 전달속도가 장점이자 단점으로 작용합니다. 전달 속도가 높아짐에 따라 전세계 어디서든 정보를 빠르게 접할 수 있지만 이에 따라 무분별한 악플이 증가할 수 있단 문제점도 발생합니다. (이후 답변은 기억 나지 않음)"},{"q":"문제를 해결하기 위해 사회적으로 어떻게 해결할 수 있나요?","a":"이러한 문제점들을 해결하기 위해서는 정부 주도의 강력한 법적 제재가 필요하다고 생각합니다. 이에 대한 예시로서 독일의 경우에는 지난 2010년대 악플관 관련한 문제들이 사회적으로 많은 문제였습니다. 하지만 악플에 관하여서 처벌수위를 높이는 법안을 통과시켰고 통과 이후에 악플의 수가 줄어들었다는 연구결과 또한 존재한다 알고 있습니다."},{"q":"연구결과가 나와있다 하였는데 출처가 어디입니까?","a":"예전에 BBC에서 악플과 관련한 법안 강화에 대한 특집기사에서 언급되었던 부분입니다."},{"q":"기억나지 않음","a":"기억나지 않음"},{"q":"마지막으로 하고 싶은 말 해주세요.","a":"저는 아직까지 폭넓은 시각을 가지지 못한 고등학생입니다. 하지만 가천대학교의 자유전공학부에 입학하여 다양한 학문들을 직접 경험하고 탐구하고 싶습니다. 또한 이것들을 바탕으로 하여 사회적으로 어려움을 가지고 있으신 분들을 도와 사회적평등을 지향하고 공공복지 실현에 앞장서는 기자라는 꿈을 실현시키기 위해 가천대학교와 함께 성장해나가고 싶습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"자유전공학부(자유전공)","jeonhyeong":"학생부종합(가천바람개비전형)","method":"생기부 기반 블라인드 면접","notes":"주도적 면접(무슨 경험이 있나~)가 아니라 직접 집어주는 형식으로 면접이 진행되기 때문에 놓치는 부분 없이 여러번 읽고, 대답을 준비 해야함.면접을 하면서 상황을 판단하고 마무리 멘트에 임팩트를 줄지, 흐름을 타 자연스럽게 마무리 할지 정해야 함.(본인은 면접때 실수를 해 만회용으로 임팩트를 주려 했음)","qa":[{"q":"등차수열과 등비수열이 무엇인지 설명할수 있나?","a":"수열은 수들이 일정한 규칙에 따라 나열된 것을 의미하며, 등차수열은 수 간의 차이가 일정하게 더하거나 빼져 이루어져 있고, 등비수열은 수 간의 차이가 일정한 크기로 곱해지거나 나누어져 있습니다. 등차수열은 일상에서 많이 사용되어 있는데, 공항 근처 고도 제한이 걸린 지역의 아파트를 보면 공항에서 멀어질수록 층수가 일정하게 증가하는걸 볼수 있습니다."},{"q":"꿈이 철도기관사인데 왜 자율전공에 지원했나?","a":"어렸을 때 경험으로 철도기관사라는 꿈을 막연히 동경했고, 그 꿈을 이루고 싶었습니다. 하지만 고등학교에 진학하고 배워가며 이 꿈에 대해 고민한결과, 이쪽 진로의 미래와 확장성이 좋지 않다는걸 깨달았고, 사람과 소통하며 아직 내가 경험할게 많이 남았구나 라고 생각해 자유전공에 지원했습니다."},{"q":"자유전공에 합격해 입학하면 어떻게 학습할 것인가?","a":"사람과 소통하는 것이 내게 매우 중요하다. 그래서 학교 동아리, 학생회 등 여러 사람들과 대화하고 소통하며 나의 견문을 넓힐 것입니다. 자유전공 이라는 학과에 맞게 최대한 많은 경험을 해 나의 방향성을 설정하고, 전공을 선택할 것입니다."},{"q":"나중에 선택할 때 원하는 전공계열이 있는가?","a":"공과쪽을 희망합니다"},{"q":"공과쪽을 희망하면, 그것에 관련되어 읽은 책이 있는가?","a":"없습니다. 하지만 어릴때부터 공과계열, 특히 자동차 쪽을 많이 경험했고, 또 철도 기관사가 꿈이었어서 관련된 블로그나, 여러 영상, 문서등을 많이 읽었습니다. 그래서 관련된 지식이 많이 쌓여있고, 많은 시간동안 그런 쪽에 노출이 되어서 자연스럽게 희망 전공계열이 공과쪽이 되었습니다."},{"q":"마지막으로 할 말 있는가?","a":"면접때 말도 더듬거리고, 대답을 잘 못한거 같아 많이 아쉽습니다. 그래도 무사히 한 것 만으로도 만족합니다. 제가 내년에 대학에서 공부를 한다면 그 대학교가 여기가 되었으면 좋겠습니다. 그럼, 내년에 뵐 수 있으면 좋겠습니다. 감사합니다!"}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"자유전공학부(자유전공)","jeonhyeong":"학생부종합(기회균형전형)","method":"교수님 3분과 학생 1명이 이루어지는 면접생기부를 기반으로 진학의지, 인성, 봉사 등을 면접","notes":"","qa":[{"q":"가천대학교에 온다면 어떤 학업계획을 세우고 실행할 것인가?","a":"1학년때 소프트웨어 세상, 인문사회 글쓰기 등의 수업을 편협한 시각이 아닌 포용적이고 다양한 시각으로 접한 뒤 2학년 진학 후 제가 원하는 학과에 진학하겠습니다."},{"q":"3학년 언매 시간에 문장 성분 발표를 했던데 어떻게 했나?","a":"문장성분을 세 분야로 나누어 조원과 이에 대한 이야기를 나누고 PPT에 삽입하여 발표했습니다."},{"q":"3학년 사회문제탐구 시간에 청소년의 독서량과 어휘력의 상관 관계를 조사했던데, 어떻게 결론을 이끌어냈나?","a":"청소년의 독서량과 어휘력에 상관 관계가 유의미하다는 논문 자료를 찾아낸 뒤 이를 풀어내 조사에 녹였습니다."},{"q":"정확히 어떤 근거로 독서량과 어휘력이 상관 관계가 있는 것인가?","a":"학생들을 두 그룹으로 나누어 한달동안 한 그룹에는 독서를 꾸준히 시키고, 한 그룹에는 독서를 시키지 않고 한달이 지난 후 어휘력을 평가할 수 있는 설문조사를 시켜보니 독서량이 많았던 그룹에서 어휘력이 확연히 뛰어나다는 결과를 도출했습니다."},{"q":"어떤 학과를 진학하고 싶나?","a":"저는 AI 인문대학의 한국어문학과를 진학하고 싶습니다. 가천대학교 한국어문학과는 다른 학교의 한국어문학과 차별점을 가지고 있습니다. 다른 한국어문학과와는 달리 가천대학교 한국어문학과는 단순히 언어에만 국한되어 있지 않고 AI음성인식 기술, AI를 활용한 수업 등으로 학생들에게 배움을 주는 학과이기 때문에 현대 사회에 맞는 한국어의 궁극적 발전을 이끌어낼 수 있을 것이라 생각합니다."},{"q":"그렇다면 AI가 무엇이라고 생각하는가?","a":"AI는 인공지능인 것 같습니다."},{"q":"AI로 어떻게 한국어의 발전을 일으킬 수 있다고 생각하는가?","a":"AI음성인식 기술, 한국어의 발전 동향 등을 AI로 파악한다면 더욱 무궁무진한 한국어의 발전을 이끌어 낼 수 있을 것이라 생각됩니다."},{"q":"마지막으로 하고 싶은 말","a":"가천대학교는 1학년 때 학과를 선택하는 자유를 주는 학과이기 때문에 비교적 가벼운 마음으로 지원하는 학생이 많을 것이라 생각됩니다. 그러나 그 자유에는 책임이 따른다고 생각합니다. 제가 가천대학교 자율전공학부에 진학한다면 항상 그 책임감을 가지고 임할 것입니다. 저를 꼭 뽑아 주셨으면 좋겠습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"컴퓨터공학과","jeonhyeong":"학생부종합(가천바람개비전형)","method":"면접은 3대 1로 진행되었습니다. 왼쪽 교수님께서 면접을 주도하시면서 진행하셨습니다. 가운데 교수님은 수학을 중점적으로 물어보셨고 생기부에 적혀있지 않은 대답하기 어려운 질문을 하시면서 압박 면접방식으로 진행하였습니다. 오른쪽 교수님은 진로활동에 적힌 내용을 물어보셨고 웃으시면서 긴장을 풀어주시기 위한 느낌으로 진행하셨습니다.","notes":"중간에 답변을 틀려서 교수님께서 갸웃하는 반응을 보이시면서 멘탈이 나갔었는데 그런 상황이 있을 때 빨리 그 상황을 잊는 것이 중요하다고 생각합니다. 그 상황을 계속 신경 쓰다가 뒤에 나오는 질문에 대해서 질문의 의도와 조금 벗어난 답변을 했었는데 최대한 빨리 실수한 상황을 잊고 다음 답변을 준비 하는게 중요하다고 생각합니다.마지막 할 말을 교수들의 인상에 남을 수 있게 준비해 가는 것이 중요하다고 생각합니다. 기출들을 찾아보았을 때도 면접을 본 사람들의 다수가 마지막으로 하고 싶은 말에서 인상적으로 준비하여 교수들의 기억에 남게 하는게 중요하다고 하였는데 실제로 저 또한 면접중에 한번도 반응이 없던 교수들이 마지막 할 말을 듣고 반을을 하는 것을 보고 마지막 할 말을 인상적이게 준비해 가는 것이 중요하다고 생각했습니다.마지막으로 공대, 자열 계열 면접을 준비한다면 최소 생기부에 나와 있는 수학, 과학 개념에 대해서는 확실하게 공부하고 가는 것이 중요하다고 생각합니다. 그리고 그 외에 배운 수학, 과학 개념에 대해서 잘 기억이 나지 않는다면 면접을 준비할 때 모르는 개념에 대해서 질문하도록 유도되지 않게 하는 것이 중요하다고 생각합니다.","qa":[{"q":"지원동기에 대해서 말해주세요.","a":"제가 가천대학교 컴퓨터공학과에 지원하게 된 이유는 저는 고등학교 1학년 여름방학 계절학기 정보통신 수업을 들으며 컴퓨터의 하드웨어 소프트웨어에 대해서 배우는 시간을 가져졌고 중간중간 직접 프로그래밍을 해보는 시간을 가졌습니다. 이 과정에서 제가 쓴 코드대로 프로그램이 작동되는 것을 보며 흥미를 느꼈습니다. 그 후 더욱 심화된 탐구를 진행해 보고 싶다고 생각을 하였고 2학년때는 코딩 동아리에 가입하여 친구들과 동아리를 소개하는 웹사이트를 제작해보고 수열을 이용한 게임을 제작해보는 활동을 해보며 저의 꿈을 컴퓨터공학자로 확정 지었습니다. 그래서 가천대학교는 저라는 인재를 키울 수 있는 유일한 학교라고 생각을 하여서 지원하게 되었습니다. 또한 판교와 강남IT기업과의 산학 연계를 통해 실무 경험을 쌓을 수 있는 기회와 AI 빅데이터와 같은 최신 기술 트랙을 통해 심화된 전공 지식을 쌓을 수 있다는 점이 큰 매력으로 다가왔습니다. 그리고 가천코코네스쿨을 통해 창업 지원과 글로벌 창업가로 성장할 수 있는 환경이 마련되어 있다는 점도 저의 창의력과 도전 정신을 키우기에 적합하다고 느꼈습니다"},{"q":"동아리에서 수열을 이용한 게임을 만들었다는데 그 과정에 대해서 설명해주세요.","a":"우선 제가 수열 게임을 만들게 된 이유부터 설명드리겠습니다. 수열 게임을 만든 이유는 수열이라는 개념에 대해서 공부해보니 많은 문제를 접해보는 것이 수열에 대해서 이해하는데 도움이 될 것이라고 생각하였고 지속적으로 재미있게 공부를 하려면 이것을 게임으로 만드는 것이 좋겠다고 생각하였습니다. 등차수열을 의미하는 코드는 arithmetic_sequence를 사용하였고 수열의 첫항을 start로 각항이 얼마만큼 증가하는지 나타내는 공차는 diff로 수열에 포함된 항의 개수를 n이라고 지칭하였습니다."},{"q":"등차수열의 개념에 대해서 설명해주세요.","a":"등차수열은 첫항이 있고 공차가 있을 때 공차가 양수면 첫항부터 공차만큼 증가하고 공차가 음수면 첫항부터 공차만큼 감소하는 형태로 이루어져 있습니다. 예를 들어 첫항이 1이고 공차가 2일 경우 1,3,5,7 이런식으로 증가하는것이 등차수열이라고 할 수 있습니다."},{"q":"1학년 수학에서 프로그램과 집합을 주제로 파이썬을 이용해서 집합과 수학의 공통점에 대한 보고서를 작성했는데 설명해주세요.","a":"이 당시 탐구를 하면서 잘못알고 있었던 내용이 있어서 이 내용은 정정드리겠습니다. 제가 당시 집합과 프로그램의 공통점에 대해서 탐구할 때 파이썬으로 집합을 구현하는 것을 집합과 프로그램의 공톰점이라고 생각하였습니다. 하지만 추후 다시 탐구 내용애 대해서 공부해보는 과정에서 제가 탐구한 내용은 집합과 프로그램의 공통점이 아니라 수학에서 집합의 개념을 프로그램에 그대로 옮겨 놓은 형태라는 것을 깨달았습니다. 그래서 제가 탐구한 내용은 집합과 프로그램의 공톰점이 아닌 집합의 개염을 프로그램에 옮겨 놓은 형태라고 정정하겠습니다."},{"q":"수2에서 경사하강법에 대해서 탐구했는데 경사하강법에 대해서 설명해주세요.","a":"경사하강법은 함수의 기울기를 구하고 경사의 절댓값이 낮은 쪽으로 계속 이동시켜 최저점에 다다를때까지 반복하는 방법의 기술입니다."},{"q":"경사하강법의 단점은 무엇인지 설명해주세요.","a":"경사하강법의 단점은 데이터 손실 문제라고 설명할 수 있습니다. 최저값을 찾는 과정에서 앞에서 구했던 데이터들은 소실되면서 최종적으로 결괏값을 도출할 때 영향력을 발휘하지 못한다는 단점이 있습니다.(틀린 답변)"},{"q":"미적분에서 역함수의 미분법을 이용해서 응용문제를 해결했는데 설명해주세요.","a":"우선 f(g(x))=x가 있을 때 미분을 하면 f′(g(x))⋅g′(x)=1의 형태가 된다는 것을 설명하였고 이를 문제에 대입하여서 문제를 해결하였습니다."},{"q":"확률과 통계에서 베이즈 정리를 이용한 스팸 이메일 필터링 방법에 대해서 탐구했는데 설명해주세요.","a":"베이즈 정리라는 것은 사전확률을 기반으로 사후 확률을 도출해 내는 이론이라고 설명할 수 있습니다. 이것을 스팸 이메일 필터링에 적용을 해보면 모든 메일에서 스팸이메일과 스팸 이메일이 아닌 것을 구분하여 사전 확률을 도출합니다. 그 후 스팸 이메일이 무엇인지 판단하기 위해 스팸 이메일의 특징이라고 할 수 있는 무료, 당첨 등과 같은 단어가 포함되어 있는 경우 스팸 이메일로 분류하여 사후 확률을 구해냅니다. 이를 통해 스팸 이메일을 구분해 낼 수 있습니다."},{"q":"2학년 진로에서 로봇 코딩전문가를 만나 일상과 로봇을 어떻게 접목시킬지에 대해서 생각해 보았다는데 어떤 사례가 있을지 설명해주세요.","a":"제가 생각하는 로봇은 인간의 삶을 편하고 효율적으로 만드는 것이 가장 중요하다고 생가하였습니다. 그래서 일상에 적용된 대표적인 사례에 대해서 생각을 해본 결과 가정에 있는 기가지니, 스마트폰에 있는 빅스비와 같은 기술이 일상에 적용된 사례라고 말씀드릴 수 있습니다. 이들은 모두 사람이 직접 리모컨을 작동 시키거나 스마트폰을 작동시키지 않고 사람의 음성을 인식하여 일을 처리할 수 있기 때문에 이러한 사례가 해당 된다고 생각합니다."},{"q":"행동특성및종합의견에서 1학년때 학급반장을 했는데 그 과정에서 어려웠던 점은 무엇인지 설명해주세요.","a":"제가 처음 학급 반장을 할 때 리더라는 사람은 조금은 단호하고 엄격함이 있어야 한다고 생각하였습니다. 하지만 이러한 방식으로 학급을 이끌어 갈 때 학급 구성원들이 제가 생각했던 것과 다르게 저를 불편해하고 그 과정에서 학급에서 의견 전달과 소통에 어려움이 있었다고 생각을 합니다. 그래서 이러한 문제를 해결하기 위해 좀 더 친구들이 편하게 의견을 내고 소통할 수 있는 분위기를 만들어 주려고 기존의 태도를 바꾸면서 해결했다고 생각합니다."},{"q":"마지막으로 할 말 간단하게 10초정도 이야기 해주세요.","a":"사람들은 컴퓨터와 인간을 반대되는 개념으로 생각합니다. 하지만 저는 그렇게 생각하지 않습니다. 제가 생각하는 컴퓨터공학은 링컨 대통령이 했던 말과 비슷하게 인간의 인간에 의한 인간을 위한 길이 컴퓨터 공학이 가야할 길이라고 생각을 합니다. 또한 저도 그 길에 이바지하는 사람이 되겠습니다. 감사합니다.지원동기는 학교에 대한 설명이 아니라 자신의 학과와 관련한 성장과정을 성명하는 것이기 때문에 지원동기를 준비할 때는 학교에 대한 이야기보다는 자신이 어떤 과정으로 학과를 위해 준비해 왔는지를 구체적으로 설명하는 것이 중요하다고 생각합니다. 인터넷 유튜브에서 자료를 찾아보았을 때 학교에 대해 공부해 간 내용을 지원동기에 넣어서 설명하였더니 교수님들의 반응이 좋았다는 이야기를 들어서 저 또한 지원동기에 학교에 대한 설명을 넣어서 설명했더니 교수님들이 그 내용에 대해서 자세히 들으려고 하는 태도는 아니었습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"패션산업학과","jeonhyeong":"학생부교과(지역균형전형)","method":"3:1 대면 면접 생기부 기반 진학 의지 확인","notes":"","qa":[{"q":"학과에 지원하게 된 동기","a":"저는 버추얼 패션 디자이너가 되어 지속가능한 패션삽업을 이끌어나가고싶은 지원자입니다 저는 독서시간에 ai와 패션산업의 미래와 관련한 글을 쓰며 ai를 주체적으로 사용하는 직업에 흥미가 생겼고 버추얼디자이너라는 꿈으로 키워나갔습니다.가천대학교 교수님들께서 디지털기술과 연관도니 논문을 활발히 쓰시며 학생들을 위해 구축해주신 최신식 수업 기자재들을 이용한 수업은 저의 꿈을 이루는데 큰 디딤돌이 될수있을것이라 생각하여 지원하게 되었습니다."},{"q":"버추얼 패션 디자이너에 대한 정보","a":"기억안남"},{"q":"ai기술을 적극 활용한 좋아하는 디자이너나 브랜드를 말하고 이유도 함께","a":"좋아하는 브랜드는 마땡킴이라 말하고 하지만 실제로 ai기술과 관련한 마케팅전략을 쓰고있다는 것은 몸소 느끼지 못했다는 식으로 말함"},{"q":"오늘 입고온 옷의 컨셉이 무엇인가요?","a":"셔츠 위에 하늘색의 가벼운 자켓을 걸쳐 화사함과 동시에 단정함을 갖춘 옷으로 입어보았습니다"},{"q":"독서시간에 쓴 패션업계의 노동문제에 대한 내용","a":"자라기업의 실제 사례를 들며 노동자의 열악한 안전조건와 근무환경을 문제점으로 들며 노동자도 곧 소비자가 될수있음을 인지하고 기업은 노동자에 대한 우대정책을 마련해야한다고 말함"},{"q":"마지막 할말","a":"저는 3학년 마케팅과 광수 수업시간에 브랜드를 런칭했던 경험이 있습니다 가천대학교에 입학한다면 이를 바탕으로 하여 4학년때 실시되는 p-학기제(집중학기제)때 친구들과 함께 가상시착서비스를 적극 도입한 브랜드를 런칭해보고 싶습니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"화공생명배터리공학부","jeonhyeong":"학생부종합(가천바람개비전형)","method":"면접관 3명, 수험생 1명의 개별면접/ 블라인드 면접/ 10분 내외","notes":"꼬리 질문 조금 있음.대기실에서 대기순서대로 불려나가 면접고사장 앞에 앉아서 기다리는 시간이 있음.면접보면서 중간에 똑똑 소리가 들린다면 10분이 거의 다 지난것임.거의 3학년 활동에 대해서 물어보셨음.다들 너무 친절하시고 들어갔을 때 큰소리로 반겨주셔서 당황했음.","qa":[{"q":"지원동기 말씀해주세요.","a":"안녕하십니까. 저는 배터리에 대한 관심을 화학실험 수업을 통해 길러왔습니다. 그리고 배터리시뮬레이션 수업과 이차전지실습 수업을 진행하는 가천대학교의 화공생명배터리공학부에 관심을 가지게 되었습니다. 그러던 중 가천대학교에서 진행하는 이차전지대학사업에 참여하여 배터리 기술에 대한 지식을 배우고 싶다고 생각했습니다. 이러한 관심으로 가천대학교 화공생명배터리공학부에 지원하게 되었습니다."},{"q":"교육과정 알아보고 온 것 같은데 배터리시뮬레이션을 통해 어떤 것을 얻고 싶나요?","a":"제가 연구한 배터리가 안전성과 효율성 측면에서 어떤지 확인하고 싶습니다."},{"q":"배터리에 대한 관심이 많은 것 같은데 전고체 배터리와 액체 전해질을 사용하는 기존 배터리와의 차이점을 아시나요?","a":"네! 알고있습니다. 전고체 배터리는 기존의 배터리와 다르게 고체 전해질을 사용하여 기존 배터리의 폭발 위험성을 줄이기 위한 요소들을 없애고 그 부분에 활물질을 채움으로써 효율성을 높일 수 있었습니다."},{"q":"고체 전해질의 종류 중 아는 것이 있나요? 000과 000 등 들어본 적 없나요?","a":"들어는 봤으나 자세히는 잘 모릅니다. 대학에 진학하여 자세히 배워보고 싶습니다."},{"q":"화학반응속도론에 대해 탐구했던데 농도 말고도 속도에 영향을 미치는 다른 요소 뭐가 있는지 아나요?","a":"네! 온도와 촉매입니다!"},{"q":"화학 수업에서 촉매에 대하여 탐구를 진행한거 같은데 촉매의 역할이 무엇인지 알고 있나요?","a":"네! 촉매는 최소한의 활성화에너지를 사용하여 화학 반응을 더 잘 일어나게 하는 역할을 합니다."},{"q":"촉매를 나노로 사용해야하는 이유가 있을까요?","a":"촉매는 나노로 활용했을 때 표적기관에 더 잘 도달할 수 있기 때문입니다."},{"q":"생명과학 분야에서는 그런데 화학반응에서는 1g의 촉매와 한 덩어리의 촉매 중 어떤 것이 더 잘일어난다고 생각하나요?","a":"(이 때 면접관님의 질문의 의도를 잘못이해하고 다른 답변했다가 다시 질문해주셔서 답변함) 저는 1g의 촉매가 더욱 반응이 잘 일어난다고 생각합니다. 왜냐하면 덩어리의 촉매를 사용한다면 화학 반응을 위해 덩어리의 촉매를 분해하는데 에너지가 더욱 쓰일 것이고 그 에너지만큼 에너자 효율 또한 낮아져 화학반응이 덜 일어날 것이라고 생각하기 때문입니다."}],"src":"울산광역시교육청 「2025 대입 면접후기 자료집」","year":"2025학년도"},{"univ":"가천대학교","dept":"간호학과","jeonhyeong":"지역인재Ⅰ","method":"서류 확인 면접 / 1개 서류 면접방(10분)","notes":"","qa":[{"q":"시간이 짧아 중간에 끊길 수 있어요 시간이 다 되면 밖에서 노크 소리 들려요 너무 당황하지 않으셔도 됩니다","a":"네"},{"q":"자기소개 간단하게 해주세요","a":"저는 환자의 심리까지 치료할 수 있는 의사소통 역량을 갖춘 중환자 전문 간호사를 꿈꾸고 있는 면접번호 00번 입니다. 여러 진료과 팀들이 모여 환자의 상태에 대해 의논하는 경우가 많은 중환자실의 특성상 환자와의 의사소통 능력뿐만 아니라 공동체간의 의사소통 능력도 중요하다 생각되어 ‘환자의 안전을 위한 의사소통’ 이라는 책을 읽고 의사소통 기술 중 SBAR의 장점과 한계에 대해 보고서를 작성하는 진로 탐구 활동을 진행했습니다. 특히 가천대 간호학과에서는 간호에 대한 과학적인 지식과 언어적 상호작용을 기를 수 있는 DNA(Day of Nursing Activity), 간호학술제, 간호야와 같은 다양한 행사를 제공하고 있어 중환자 전문 간호사의 실무 능력을 기르기에 적합하다고 생각했습니다. 가천대 간호학과에 진학하여 다양한 행사 참여를 통해 의사소통 역량을 갖춘 중환자 전문 간호사로 성장하고 싶습니다."},{"q":"생2에서 리포좀 역물 전달 메커니즘에 대해 탐구 했는데 거기에 대해 자세히 말해볼 수 있을까요?","a":"리포좀은 인지질 이중층 구조를 가진 인공 소포로, 세포막과 유사한 성질을 가지고 있어 체내에서 안정성이 높습니다. 리포좀을 사용하면 약물이 표적 세포에 도달하기 전까지 보호될 수 있으며, 표적 세포에 도달했을 때만 약물이 방출되도록 조절할 수 있습니다. 리포좀은 표적 세포의 수용체와 결합하여 약물이 건강한 세포에는 영향을 덜 미치고, 암 세포에만 선택적으로 작용하게 함으로써 부작용을 줄이고 치료 효과를 높일 수 있습니다. 반면, 일반적인 약물 전달 방식은 약물이 체내에서 무작위로 분포되어 건강한 세포와 암세포 모두에 영향을 미칠 가능성이 큽니다. 그 결과 환자가 심각한 부작용을 겪게 될 수 있습니다."},{"q":"응급상황 프로토콜에 대해 조사 했다고 하는데 그 중 하나 기억나는 프로토콜이 있을까요?","a":"뇌출혈 프로토콜의 시나리오가 가장 기억에 남습니다. 고혈압성 뇌출혈 환자를 가정하여 길거리에서의 프로토콜과 병원에서의 프로토콜을 나누어 설명하였습니다. 길거리에서 고혈압성 뇌출혈 환자 발생시, 119에 신고한 후 뇌 압력을 완화시키기 위해 환자의 머리를 약간 높여 고정시킵니다. 환자의 상태를 계속 모니터링 하며 구급차가 올 때 까지 대기합니다. 병원에서 고혈압성 뇌출혈 환자를 받았을 때에는, CT스캔을 통해 뇌출혈의 위치와 정도를 확인하고 출혈의 원인을 찾습니다. 그 후 원인과 정도에 따라 약물치료, 수술 등의 적절한 치료를 시행합니다."},{"q":"후성유전학에 대해 조사 했다고 하는데 후성유전학이란 무엇인지에 대해 설명해주세요","a":"후성유전학이란 유전자의 염기서열변화 없이 유전자 발현이 조절되는 현상을 연구하는 학문입니다. 후성유전학적 변화의 예로는 DNA메틸화가 있습니다. DNA메틸화란 염기 중 하나인 사이토신의 다섯번째 탄소에 메틸기-네, 여기까지 듣겠습니다."},{"q":"청소년 마약에 대해 탐구 했다고 하는데 뇌에서 중독 일어나는 과정에 대해 이야기 할 수 있을까요?","a":"중독의 주요원인은 내성입니다. 동일한 양의 약물이라도 약을 지속적으로 사용함에 따라 점점 더 작은 반응을 만들어 내며 동일한 반응을 유지하기 위해 점점 더 많은 양의 약물을 섭취하려는 과정으로 이어집니다."},{"q":"어떻게 내성 생기는지 아는지 아나요?","a":"…잘 모르겠어요-아 괜찮아요 전문적인 내용이라 그냥 물어봤어요"},{"q":"경제수학에서 의료복지에 대해 탐구했다고 하는데 우리나라에서의 의료복지에 관해 설명해주실 수 있을까요?","a":"우리나라는 국민을 대상으로 하는 복지를 제공하고 있의며 전국민의 의료 접근성을 향상시킬 수 있다는 장점이 있습니다."},{"q":"의사소통 관심 많은 것 같은데 기억 남는거","a":"SBAR이란 SBAR은 situation, background, assessment, recommendation의 줄임말로 환자의 정보 누락을 예방하고 빠르고 정확한-네, 여기까지 들을게요(똑똑똑)"},{"q":"마지막으로 하고 싶은 말 해주세요","a":"가천대학교의 인재상은 지성인, 실천인, 전문인으로 알고 있습니다. 저는 3년 동안 선도부 활동, 영어 학습지 도우미, 방학 중 청소 활동 등에 참여하며 봉사정신을 길렀으며, 문제 해결 역량을 기르기 위해 마약류 의약품 오남용, 소아 청소년과 폐지와 같은 이슈를 조사하고 해결책을 제시하는 등 다양한 탐구 활동을 수행해왔습니다. 이렇게 한계를 넘는 도전을 계속 시도하는 저의 자세가 가천대학교의 인재상에 부합하다고 생각합니다. 가천대학교 간호학과에 입학하여 수준 높은 교육을 받으며 전문성을 갖춘 간호사로 거듭나고 싶습니다. 감사합니다.1단계에서 진로선택과목만으로 성적을 계산하고 7배수를 선발하는 전형에 매우 적합한 경특이점우였고 2단계 면접에서 좋은 점수를 얻었을 것으로 생각함. 합/불 분석최초합아쉬운 점면접에서 준비한 것을 대부분 대답할 수 있어서 크게 아쉬운 점은 없었음."}],"naesin":"3.38","result":"최초합격","resultNote":"","suneung":"최저기준없음","type":"일괄합산( ) 단계형( 0 ) 【1단계】 서류100(7배수) 【2단계】 1단계50+면접50","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"간호학과","jeonhyeong":"학생부 종합/가천바람개비","method":"일반 면접 (블라인드 평가)","notes":"","qa":[{"q":"지원동기를 말해주세요.","a":"제가 초등학교 시절 가족 중 두 사람이 동일한 희귀병으로 고생하셨습니다. 그때 가족이 환자에게 얼마나 중요한 역할을 하는지 깨달았고, 환자에게 심신의 안정을 주는 것이 가장 중요하다고 느껴 조용하고 편안한 분위기를 조성해 회복을 돕는 작은 간호를 실천했습니다. 이러한 경험을 통해 우리 가족뿐만 아니라 다양한 질병으로 고통받는 환자와 그 가족들에게 도움을 주고 싶다는 목표를 가지고 간호사를 희망하게 되었습니다. 저는 ‘작은 씨앗이 큰 숲을 이룬다’라는 말처럼, 저의 작은 노력들이 모여 큰 변화를 이끌어 낼 수 있다고 믿습니다. 이는 불모의 땅에 한 그루의 나무를 심는 마음으로 가천대학교 길병원을 운영하는 정신과도 닮아 있다고 생각하여 가천대학교 간호학과에 깊이 이끌리게 되었습니다. 또한 4차 산업혁명 시대에 맞는 교육 프로그램과 국제화 시대에 맞춰 전 세계 사회적 약자를 돌볼 인재를 양성하는 가천대학교 간호학과의 비전은 저의 성장 가능성을 무한히 넓혀줄 것이라고 생각하여 가천대학교 간호학과에 지원하게 되었습니다."},{"q":"생명과학2 시간에 리보솜에 대해 탐구했는데, 리보솜과 암 증식 사이의 관계를 설명해주세요.","a":"이노신산 탈수소 효소의 양이 늘어나면 GTP 생산이 증가하게 됩니다. 암세포에서 GTP 생산이 증가하여 핵소체에서 리보솜 합성에 사용되면 암 증식을 촉진합니다. 여기서 핵소체의 크기가 커질수록 리보솜은 더 많이 생산되어 암세포의 대량 생산으로 이어지게 됩니다."},{"q":"당뇨병에 대해서도 관심을 가지고 공부한 거 같은데, 임신성 당뇨병에 대해 설명해주세요.","a":"우선 당뇨병은 인슐린의 작용 이상으로 소변으로 당이 검출되는 질환입니다. 임신성 당뇨병은 임신 중 처음 발견되었거나 임신의 시작과 동시에 생긴 혈당 조절 이상을 말합니다. 대부분은 출산 후 정상화되지만 임신 중 혈당 조절의 정도가 정상 범위를 벗어나게 되면 신생아 합병증을 유발하게 됩니다. 신생아 합병증으로는 ..."},{"q":"통합과학 시간에 RNA 백신에 대한 보고서를 작성했는데, RNA 백신의 작용원리와 장단점에 대해 설명해주세요.","a":"RNA 백신은 단백질 발현을 유도하는 mRNA를 체내 전달하고 우리 몸이 내인성 항원을 직접 만들도록 유도하여 그 항원에 대한 면역을 가지도록 합니다. 이러한 mRNA 백신은 개발 속도가 매우 빠르다는 장점이 있습니다. 이러한 빠른 개발 속도로 인해 신종 감염병과 그의 변이 출현 속도가 점점 빨라지는 현재 추세에서 신속한 백신 개발을 가능케 할 수 있습니다. 그러나 mRNA의 안정성을 향상시키기 위해 고안된 지질나노입자 기술로 인해 다른 백신들과 다르게 상온에서는 보관이 불가능합니다. 그로 인해 냉동이나 초저온 상태에서만 저장 및 유통이 가능하다는 단점이 있습니다."},{"q":"‘죽음과 죽어감’을 읽고 소통과 돌봄에 대한 소양을 넓혔다고 하는데, 죽음의 5단계에 대해 설명해줄래요?","a":"죽음의 5단계는 부정, 분노, 타협, 우울, 수용으로 나뉩니다. 첫 번째 부정 단계에서는 죽음에 대한 통보를 부정하며 현실을 받아들이지 않으려 합니다. 두 번째 분노 단계에서는 병의 회복 가능성이 없음을 깨달으며 자신을 둘러싼 세계에 대한 원망과 분노를 표출합니다. 세 번째 ..."},{"q":"COX의 개념에 대해서도 잘 아는 거 같은데, 설명해주세요.","a":"COX는 프로스타글린딘 합성 단계를 촉매하는 효소로, COX-1과 COX-2라는 형태로 나뉘게 됩니다. COX-1은 위, 신장 점막에 많이 위치하여 항상성을 유지해주는 프로스타글란딘 합성 역할을 해주고, COX-2는 염증, 통증, 열에 관련된 프로스타글란딘 합성을 시켜주는 역할을 합니다."},{"q":"메스라는 동아리에서 다양한 활동을 했는데, 이는 어떤 동아리이며 동아리에서 했던 활동 중 가장 기억에 남는 활동에 대해 이야기해주세요.","a":"우선 메스는 생명과학 분야에 탐구하는 동아리입니다. 저는 1학년 동아리 활동 시간에 암세포를 관찰하고 항암제의 원리를 탐구한 활동이 가장 기억에 남습니다. 이 활동을 하며 우리나라가 인구 고령화에 따라 암 발생이 꾸준히 증가하고 있다는 점을 알게 되었으며, 이를 바탕으로 암의 전문적인 연구와 치료에 힘쓰고 있는 ..."},{"q":"암세포를 어떻게 관찰했나요?","a":"저는 암세포를 계대배양하고 이를 현미경을 활용하여 관찰했습니다. 여기서 계대배양은 세포가 과도하게 분열하게 되면 영양분을 제대로 공급받지 못하기 때문에 세포가 70~80% 자라게 되면 암세포를 다른 배양 접시에서 배양하는 방법을 말합니다."},{"q":"그럼 마지막으로 하고 싶은 말이 있나요?","a":"우선 저에게 면접 기회를 주셔서 감사합니다. 저는 스스로를 객관적으로 되돌아보며 단점을 개선하기 위해 항상 노력하며 고등학교 3년동안 성적을 꾸준히 향상시킬 수 있었습니다. 가천대학교 간호학과에 진학하여 훌륭하신 교수님들께 좋은 간호를 배워 가천대학교를 빛낼 인재로 성장하고 싶습니다.특이점없음성적이 전년도 합격자에 비교하여 높은 편이었기에 면접이 관건이었음. 50프로나 반영되기 합/불 분때문에 면접 준비를 열심히하였고, 그 결과 후보 순위도 좋게 받아 합격할 수 있었던 것이석라고 생각함.아쉬운 점없음"}],"naesin":"2.34","result":"충원합격","resultNote":"후보 3 순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( 0 ) 【1단계】 서류100(5배수) 【2단계】 1단계50+면접50","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"게임, 영상학과","jeonhyeong":"수시/학생부","method":"생기부, 제출한 포트폴리오 기반 / 제출서류 기반 질문 및 개인 질문","notes":"","qa":[{"q":"우리 학교에 지원한 이유","a":"나와 관심사가 같은 사람들과 함께 프로그래밍 하며 멋진 게임을 개발하면서 남다른 실무 중심 경험을 쌓으며 게임 개발자라는 꿈을 이루어 나가고 싶었습니다."},{"q":"우리 회사에 지원한 이유","a":"이 회사의 자유로운 사내 복지 및 문화, 그리고 벤쳐기업 특유의 창의적인 도전정신이 마음에 들었습니다."},{"q":"포트폴리오 및 생기부에 적힌 활동은 모두 본인 혼자서 한 활동인지.","a":"혼자서 유투브를 참고 해 가면서 독학하면서 활동했습니다."},{"q":"왜 혼자서 했는지","a":"주위에 게임 개발에 관심있는 사람이 없었을 뿐더러, 그나마 코딩에 관심이 있던 친구는 수능 공부를 하느라 시간이 없다며 코딩하기를 거부했다."},{"q":"그래픽(그림)은 왜 혼자서 했는지","a":"그림 그리기에 관심이 있어서 실력을 쌓을 겸 혼자 그렸다."},{"q":"마지막으로 만든 게임이 무엇인지.","a":"아두이노 사격게임을 마지막으로 만들었다. 그리고 현재 게임 코딩 대회 작품을 준비하고 있었습니다."},{"q":"그 게임은 어떤 게임인지","a":"(게임에 대한 설명)스토리 위주의 도트 퍼즐 게임(으로 장황하게 설명이 길어 생략)"},{"q":"3D 프로그램은 어떤 활동이었는지","a":"태양계 시뮬레이션을 만들기 위해 제작한 프로그램으로 3D를 구현하기 위해 선형대수학에 관한 책을 읽었고, 직접 가설을 세우고 실험을 통해 검증해가며 데이터상의 좌표를 3D로 표현하기 위한 원리를 탐구해나간 활동이었습니다. (원리 설명함.)"},{"q":"마지막으로 하고싶은 말","a":"(잘 기억 안남) 저는 좋아하고 재밌는것에 몰두한다는 장점을 가지고있습니다. 그리고 제가 좋아하는 것은 다름아닌 게임 개발 입니다. 저는 이 과에서 다같이 재밌는 게임을 개발해나가고 싶습니다.특이점조기취업형 계약학과, 블라인드 면접 아님, 충원합격 순위 안보여줌합/불 분석1단계 합격 후 2단계에서 불합격나름 열심히 준비하고 답변을 하였으나, 내가 갖고 있는 장점을 다 보여주지 못한 것 같은 아쉬운 점아쉬움이 남습니다."}],"naesin":"4.79","result":"불합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( 0 ) 【1단계】 서류 100% 【2단계】 면접:전단계성적=50:50","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"경제학과","jeonhyeong":"학생부종합/가천바람개비","method":"학생부 확인형 / 대기실 대기 → 면접실 입장 → 면접 진행(10분 내외 / 면접관 3명) → 퇴장","notes":"블라인드 면접, 성적 블라인드","qa":[{"q":"네 저희학과에 지원해주셔서 감사합니다. 긴장하시지 마시고, 답변은 30초에 1분내로 부탁드리겠습니다. 길면 저희가 끊을 수도 있습니다. 밖에서 노크 소리 들리면 당황하시지 마시고 계속 말 하시면 됩니다.","a":"넵!"},{"q":"지원동기 말해주세요","a":"네 안녕하십니까! 신뢰를 바탕으로 최고의 수익을 보장하는 자산관리사가 되고 싶은 지원자입니다. 저는 고등학교 떄부터 꾸준히 모의투자와, 주식투자동아리를 기획하고 운영하였습니다. 이 활동을 통해서 경제흐름과 재무제표를 활용하여 높은 수익률을 얻어낼 수 있었습니다. 가천대학교는 ipp일학습병행프로그램, p실무프로젝트가 있는 것으로 알고있습니다. 이 활동을 통해서 제 가장 중요한 역량인 고객과 소통능력, 금융데이터 해석 능력을 키울 수 있을 뿐만 아니라 이론을 실무에 적용해서 실무 능력을 키워낼 수 있을 거 같아서 지원하게 되었습니다."},{"q":"수2 시간에 중적분에 대해서 탐구했는데 중적분을 어떻게 구하죠?","a":"일변수 함수를 각각 적분하여서 구할 수 있습니다."},{"q":"확통시간에 몬티홀 딜레마에 대해서 탐구했는데 누가 더 유리한가요?","a":"문을 봐꾸는 것이 유리합니다."},{"q":"(꼬리 질문) 그 이유는?","a":"문을 바꾸지 않는 것에 확률은 1/3이고 문을 봐꾸는 확률은 2/3확률이기 때문에 문을 바꾸지 않는 것이 유리합니다."},{"q":"거기서 진행자가 어디 있는지 모르면 확률이 어떻게 되는지? (질문이 정확하게 기억나지 않음)","a":"잘 기억나지 않습니다. 교수...(말 끊음)"},{"q":"네~ 알겠습니다. 다음 질문 드릴게요. 경제 시간에 일본이 저금리를 유지하고 있다고 했는데 왜 저금리를 유지하고 있는지?","a":"일본은 버블경제로부터 디플레이션을 겪고 있습니다. 그래서 일본은 경제성장을 하기 위해서 저금리를 통해서 통화량을 늘려서 경제성장을 촉진시키기 위해서 저금리를 유지하고 있습니다."},{"q":"그러면 엔저가 우리나라에게 주는 영향이 뭐가 있을까요?","a":"일본에 엔저 현상이 나타나게 되면, 우리나라에 엔 캐리 트레이드를 통해 엔화가 들어올 수 도 있습니다. 왜냐하면 엔저현상으로 인해서 일본은 저금리를 유지하고 있고 우리나라는 일본보다 고금리를 유지하고 있기 때문에 이자가 낮은 일본에 엔화를 빌려서 우리나라 투자를 하게 되는 엔캐리 트레이드가 발생하고 일본에 엔화가 유입되어서 경제성장이 발생할 수 있습니다."},{"q":"엔저 현상이 우리나라 수출에 주는 영향은요?","a":"엔저현상이 발생하게 되면 우리나라 수출에 악영향을 주게됩니다. 왜냐하면 일본에 엔저현상으로 인해서 우리나라 상품보다 가격이 낮게 측정되어서 가격경쟁력이 높아지고 우리나라 일본 상품보다 가격이 높게 측정되어서 가격경쟁력이 낮아져서 우리나라 무역에 안 좋은 영향을 미칠 수 있습니다."},{"q":"네 잘 대답하셨네요. 1학년 진로시간에 경제학 콘서트를 읽고 게임이론에 대한 개념을 확립했다고 했는데 어떤 개념?","a":"게임이론은 상대방에 행위를 고려하여 최적의 결정을 하는 경제학 이론입니다. 예를 들어 치킨 게임이 있습니다. 달려오는 두 차가 있는데 한명이 피하게 되면 피하지 않은 쪽이 이기고 둘다 피하지 않으면 죽게되고 둘다 피하면 아무도 승리하지 않게 됩니다. 이로인해서 상대방의 반응을 고려해서 최적의 반응을 고려를 해야합니다."},{"q":"마지막으로 하고싶은 말 10초 해주세요.","a":"저는 가천대학교 경제학과에 입학해서 글로벌 경제인 인재로 양성될 자신이 있습니다. 저는 고등학교 2,3학년 떄 일본,미국,중국등 다양한 해외시장에 대해서 탐구를 하고 금리, 부동산 등을 파악하였습니다. 입학하게 된다면, 동북아 경제를 듣고 해외 경제를 배우고 글로벌 인재로 나아가도록 하겠습니다. 특이점수학 교과 관련 질문을 많이 물어봄.합/불 분석경제 관련 탐구 활동(엔저, 게임이론 등)의 경우, 대비를 해갔던 질문이라 잘 대답함.확률과 통계 몬티홀 딜레마 질문에 미흡하게 답변한 것. 수학 관련 질문에 대비를 더 해두아쉬운 점었으면 하는 아쉬움이 남음."}],"naesin":"-","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류 100% 【2단계】 면접 50%+서류 50%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"물리치료학과","jeonhyeong":"학생부종합/가천바람개비","method":"서류 확인 면접(공통 질문 + 전공 기본지식 + 서류 확인) / 약 7~8분 동안 3대1 면접 전자기기 보관함이 따로 준비되어 있지 않아 각자 가방에 넣어야 하므로 가방을","notes":"반드시 지참(옷 주머니 보관 불가), 사전 고지된 면접 시간은 10분이나 대기실에 서 안내 위원이 7분으로 고지하며 시간이 촉박하기 때문에 매우 긴장됨. [질문 내용1]","qa":[{"q":"우리 학교의 물리치료학과에 지원한 동기 말해주세요.","a":"저는 국가대표팀의 어머니, 궁극적으로는 세계 공동체의 어머니가 되고 싶은 미래의 물리치료사입니다. 지원 동기는 첫째, 가천대학교의 전공선택과목인 재활심리학, 교양과목인 인성과 리더십을 통해 세계 공동체를 소중히 하는 물리치료사, 신체적인 재활과 심리적 고통까지 치료하는 물리치료사로 성장하고 싶기 때문입니다. 저는 3년 동안 학급 임원으로 작은 사회인 학급에서부터 봉사하며 사랑과 나눔을 실천해 왔습니다. 이제는 가천대학교에서 세계 공동체에게 박애를 실천하는 물리치료사로 성장하고 싶습니다. 둘째는 가천대학교의 근거중심 물리치료실습 과목을 통해 혁신적이고 지속가능한 물리치료를 제공하고 싶기 때문입니다. 저는 특히 근거중심 물리치료에 관심이 많고 또 탐구 경험도 있습니다. 저는 가천대학교 물리치료학과에서 제가 탐구하며 배웠던 것들을 더욱 발전시키고 싶기 때문에 지원했습니다.[질문 내용2]"},{"q":"우리 학과 홈페이지 들어가보셨나요? 도수치료, 운동치료, 재활치료에 대해서 간단하게 각각 설명해 주세요.","a":"먼저, 도수치료란 관절가동술, 관절교정, 연부조직 가동 등을 이용하여 관절을 원래의 상태로 회복하고, 통증을 줄이기 위해 물리치료사의 손이나 기구를 이용하여 치료하는 치료입니다. 운동치료란 운동을 통해 환자가 일상생활을 할 수 있도록 신체 기능을 향상시키는 치료입니다. 재활치료란 운동치료 후에 환자에 맞게 적용하여 일상생활이 가능하게 하는 치료입니다.[질문 내용3]"},{"q":"1학년 기술가정 시간에 사경에 대해 탐구하였는데, 사경이 정확하게 어떤 근육에 문제가 생긴 건지 간단하게 설명해 주세요.","a":"제가 탐구했던 것은 신생아 사경으로 출산이나 태어난 이후의 외부 요인으로 인해 목이 한쪽으로 치우치는 것으로 목 근육에 문제가 생긴 것입니다.(정확한 근육 명칭 답변 못함)[질문 내용4]"},{"q":"체육 축제에서 보건 부스를 운영했는데, 본인이 한 역할이 무엇인지 설명해 주세요.","a":"올바른 테이핑 방법과 파스 부착 방법을 사전에 연습해 현장에서 부상을 예방하고 응급 처치를 돕는 역할을 했습니다. 발목 염좌와 손목 염좌 테이핑을 실시했습니다.[질문 내용5]"},{"q":"최종 목표에 대해 말해주세요.","a":"일차적으로는 선수와 국가를 위해 헌신하는 의무트레이너가 되고 싶습니다. 하지만 최종적으로는 물리치료사 전문 파견 구호 단체를 설립해 세계의 의료 사각지대를 하나씩 없애가며 인류 전반에 기여하는 물리치료사가 되는 것이 목표입니다. 그 이유는 1학년 수업량 유연화에서 게라지 세일 수익을 우크라이나 난민 구호에 기부한 경험을 통해서 구호 단체에서 구호 활동을 하는 물리치료사가 되고 싶다고 생각했기 때문입니다. 하지만 실제로 저는 물리치료사가 팀 기반 협업에서 팔로워십뿐만 아니라 리더십과 자율성을 발휘할 수 있는 물리치료사 전문 파견 구호 단체를 설립해 의료 사각지대를 하나씩 없애가고 싶습니다.[질문 내용6]"},{"q":"마지막으로 하고 싶은 말 있으면 해주세요.","a":"제 성적이 비록 좋은 성적은 아니지만 실패는 인생의 소중한 밑거름이 된다는 이길여 총장님의 말씀처럼 부디 이를 극복하기 위해 그 뒤에 따른 제 노력을 믿고 눈여겨 봐주시어 가천대학교에서 공부할 기회를 주시면 감사하겠습니다. 서류 확인 면접이지만 공통 질문과 전공 지식에 대한 관심을 확인하는 질문이 주를 이룸. 물리치료학과 교수님이 중간에 앉아계시고 양 옆으로 입학사정관이 앉아 계심. 교수님은 긴장 풀어주시려고 눈 마주칠 때마다 웃어주시고 답변할 때 고개도 끄덕이시며 호응해 주시특이점는 반면 입학사정관분들은 무표정으로 반응함. 꼬리 질문이 아예 없음. 면접관님들께서도 급하게 질문하시고 매 질문마다 시간이 짧다는 점 유의해서 간단하게 답변하라고 말씀하실 정도로 시간이 매우 촉박해 매우 긴장됨.합/불 분석최초합격타학교 제시문 면접 준비로 인해 생활기록부 내용 숙지가 미흡했음. 또한 시간이 매우 촉박아쉬운 점하여 더욱 긴장되었고 답변을 머릿속에서 정리할 시간이 없어 횡설수설하게 되었음."}],"naesin":"3.66","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ○ ) 【1단계】 서류100(5배수) 【2단계】 1단계50 면접50","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"바이오로직스학과","jeonhyeong":"학생부종합전형/가천바람개비","method":"학생부 위주 / 시간별 대기실 대기 → 신분 확인 및 가번호 지급 → 약 10분 간 면접 진행","notes":"떨지 않고 준비한대로, 거짓말하지 않고 있는 그대로 진실성이 있게","qa":[{"q":"당뇨병에 관심이 많네요. 당뇨병의 원인에 대해 탐구하였다고 되어 있는데, 어떤 것이 있죠?","a":"네, 저는 사회적으로 당뇨병 환자가 늘었나고 있다는 점을 접하고 당뇨병을 일으키는 원인에 대해 분석해보고자 탐구를 진행하였습니다. 당뇨병은 유전적 원인, 환경적 원인, 약물 복용을 원인으로 제시하였습니다. 탐구 결과 유전적 원인이 클 것이라는 가설과 달리 환경적 요인이 가장 크게 작용한다는 것을 알게 되었습니다. 이러한 후천적 요인을 해소하기 위해 꾸준한 운동이나 식단 관리의 중요성을 제고하게 되었습니다."},{"q":"추가로 당뇨병의 종류에 대해 알고 있나요?","a":"네, 정확한 명칭은 잘 기억나지 않지만 선천적인 것과 후천적인 것으로 나뉜다고 알고 있습니다. 후천적인 것은 약물이나 운동, 식단 등 평소 생활 습관을 조절하면 해결하기 쉽지만, 선천적인 것은 죽을 때까지 약물을 달고 살아야 하며, 상대적으로 고치기 어려워 꾸준한 연구가 필요하다고 알고 있습니다."},{"q":"당뇨병을 치료하는 약물의 명칭으로 알고 있는 것이 있나요?","a":"주변에서 당뇨병을 앓고 있는 사람들의 보며 혈당 조절을 목적으로 약물을 섭취하는 것으로 알고 있습니다. 다만, 정확한 명칭으로 알고 있는 것은 없어서 추후 대학에 진학하면 배워나가도록 하겠습니다."},{"q":"고급생명과학 시간에 mTOR의 신호전달체계에 관해 탐구했네요. mTOR이 뭐죠?","a":"네, 저는 고급생명과학 시간 우울증과 같은 신경약물의 작용 원리가 궁금하여 우울증의 신호전달체계인 mTOR에 관해 탐구했습니다. mTOR은 세포의 성장, 생존, 대상 관련된 단백질을 말합니다. 우리 몸에 글루탐산계 약물이 들어오면, NMDA 수용체에 작용하고 AMPA 수용체가 상대적인 활성화가 증가합니다. 이후 체내 칼륨이온이 증가해 mTOR 신호전달체계가 활성화되면, 신경가소성을 촉진하고 시냅스 연결성이 향상됩니다. 다만, 내성이 생긴다는 단점이 있어, 이를 해소하기 위해 저는 나노입자 기반 약물전달 시스템의 응용을 생각해보았습니다. (이후는 나노입자에 대해 추가 질문을 하겠다며 답변을 끊으심)"},{"q":"안 그래도 나노입자 기반 시스템에 관해 질문하고 싶었는데, 나노입자 기반 약물전달 시스템이 뭐죠?","a":"네, 나노입자는 혈액-뇌 장벽의 미세한 틈을 통과할 수 있는 입자를 말합니다. BBB 장벽은 지질층으로 이루어져 있는데요. 코로나 백신의 원리도 이와 유사하며, 지질 기반 나노입자와 초음파를 활용하면 이러한 BBB장벽의 미세한 틈을 통과하기 쉬워 현재 상용화되어 있는 다른 약물에 비해 뇌까지 약물이 효율적으로 전달되기 쉽습니다. 다만, 아직 기술적으로 BBB 장벽 통과의 현실적 한계와 생산 비용이 높은 점, 나노입자가 체내에 장기 축적될 시 독성이나 면역 반응을 유발할 수 있다는 단점을 해소하기 위한 꾸준한 연구도 필요할 것입니다."},{"q":"BBB장벽이 무엇이죠?","a":"네 BBB 장벽은 Brain-blood barrier의 약칭으로 우리 뇌를 감싸고 있는 혈액-뇌 장벽을 칭한다고 알고 있습니다."},{"q":"약물 중독에 관해 탐구했는데, 어떤 내용인지 설명해 주시겠어요?","a":"저는 최근 전세계적으로 심각해진 마약 중독 현상을 보며, 마약의 중독 원리를 이해하고 치료 방안을 제시하고자 탐구를 진행하였습니다. 약물 섭취 초기에는 양성 피드백의 영향으로 우리 뇌에 긍정적인 감정의 자극이 강화되면 중독됩니다. 중독된 후 약물 섭취를 중단하게 되면 체내 음성 피드백의 영향으로 체내 약물에 대한 내성이 형성되어 우울, 불안, 손떨리 등의 금단 현상이 나타나는데요. 이를 치료하기 위해 결국 또 다른 의존성 약물을 사용해야 한다는 점이 충격적으로 다가왔습니다. 이에 저는 수많은 시행착오를 통해 ‘신경 서장 인자’를 직접 자극하는 약물을 연구하여, 의존성을 줄이고 뇌 회로를 재정립할 수 있는 새로운 치료제를 개발하고 싶단 생각이 들었습니다."},{"q":"졸업 후 진로 계획은 어떻게 되죠?","a":"제 1차적인 목표는 신경 질환 치료를 위해 뇌를 직접 타겟팅하는 신약을 개발하는 것입니다. 이후 수많은 연구 경험을 쌓아 의약품 분쟁 해결 및 특허에 관한 일을 진행하는 것이 2차 목표입니다. 이를 위해서는 바이오의약품의 꾸준한 연구가 필요하기 때문에 가천대의 Medixal power의 도움을 받아 전문성을 향상한 연구인이 되기 위해 노력하겠습니다. ∘인성이 면접의 40%를 차지했는데, 인성에 관한 질문은 한 개도 받지 않았다.∘3명의 면접관이 계셨고, 좌측에 입학사정관 나머지 두 분이 약대 교수님이다. 면접 전에 특이점긴장하지 말고 편하게 답하라며 아이스브레이킹을 해주셔서, 상대적으로 편안한 분위기에서 면접에 임할 수 있었다.합/불 분석최초합아쉬운 점크게 없다."}],"naesin":"2.8","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( O ) 【1단계】 서류 【2단계】 면접","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"식품생명공학","jeonhyeong":"학생부종합/ 가천바람개비전형","method":"서류(학생부) 기반 면접 / 면접실 밖에서 1분간 대기 후 약 10분간 면접","notes":"신분증 필수 지참, 전자기기 전원 끈 후 가방에 넣어둠","qa":[{"q":"지원동기가 어떻게 되시나요?","a":"안녕하십니까. 저는 식품의 미래를 보장하고픈 가번호 3번입니다. 저는 음식을 요리하는 것보다는 식품을 과학적으로 분석하고 연구하는 데 더 큰 흥미를 느낀다는 것을 깨달았습니다. 이를 통해 고등학교 3년동안 식품생명공학과 관련한 다양한 활동을 진행하며 학문적 열정을 키웠습니다. 그중 식품 관련 실험들을 진행하며 조금 더 전문적인 지식이 필요함을 느끼기도 했습니다. 따라서 식품공학 전반을 공부하며 건강하고 혁신적인 식품을 개발하는 식품연구원이 되고자 지원하게 되었습니다."},{"q":"식품생명공학은 식품 반 생명 반인데 식품공학으로 지원하게 된 것인가요?","a":"고등학교 1학년때 생명공학이라는 분야를 처음에 알게 되었다가 어릴 때부터 식품을 좋아했어서 식품과 생명공학이 합쳐진 식품생명공학이 있다는 것을 알고 지원하게 되었습니다.[그러면 식품연구원이 될 자격이 있는지 교과 세특을 통해 확인해보도록 하겠습니다.]"},{"q":"화학1 시간에 암모니아 비료에 대해서 탐구를 하셨던데 암모니아 비료가 정확히 무엇인가요?","a":"암모니아 비료는 암모니아를 이용한 화학 비료입니다. 과거에 식량이 부족하여 비료를 공급해야 되는 상황이 있었는데, 대량생산이 가능한 암모니아를 이용하여 비료를 활용해 식품을 생산하였습니다."},{"q":"이 암모니아 비료를 식품 생산에 왜 사용되는지 아시나요?","a":"아뇨. 모르겠습니다."},{"q":"생기부에 잘못 적혀있는 내용이 있는 것 같은데 아크릴아마이드가 왜 설탕에 들어있는지 아시나요?","a":"잘 모르겠습니다. 그러나 제가 알기로는 감자에 들어있는 성분과 포도당이 만나면 아크릴아마이드가 생산됩니다.[네. 잘 알고 계시네요. 근데 주로 식품에 대해서 반감을 갖고 진행한 내용을 많이 하셨네요. 하하.]"},{"q":"글루탐산모노나트륨과 가다랑어포 관련 내용에 대해 탐구하고 비슷한 맛이 난다고 하셨는데, 글루탐산모노나트륨은 MSG의 일종입니다. 근데 학생이라면 MSG와 가다랑어포 중에서 어느 것을 사용하실 건가요?","a":"저는 MSG를 사용할 것 같습니다. 비슷한 맛이 나기도 하고 예전부터 먹어왔던 맛이기에 MSG가 더 괜찮을 것 같다고 생각합니다."},{"q":"알코올발효란?","a":"알코올발효란 미생물이 당을 발효시켜서 알코올과 이산화탄소를 생산하는 발효를 의미합니다. 아 조건은 산소가 없어야 합니다."},{"q":"학급 임원으로서 리더십을 발휘하셨다고 적혀 있는데 그중 힘들었던 점은 무엇이고 어떻게 극복했는지 설명해주실 수 있나요?","a":"첫번째로 학급 인원이 많아서 자습시간에 반 분위기가 흐린 상황이 있었는데 그때 리더십을 발휘하여 침묵할 수 있도록 했습니다. 그리고 학급 인원이 많아서 협동을 해야 하는 상황이 있었을 때 다 같은 의견들이 나오지 않아 힘들었지만 모두 다같이 참여하여 협동심이 나올 수 있도록 리더십을 발휘했다고 생각합니다."},{"q":"이제 시간이 얼마 남지 않았는데 마지막으로 하고 싶으신 말씀 있으신가요?","a":"저는 음식을 좋아하는 것을 넘어, 식품에 대해 깊은 탐구심을 갖고 있습니다. 식품이 우리의 삶에서 떼려야 뗄 수 없는 중요한 요소임을 알기에, 이 식품생명공학과 분야에서 새로운 가치를 창출하고 싶습니다. 앞으로 식품생명공학과에서 공부하면서 미래지향적인 식품을 개발해보고 싶습니다. 감사합니다.주차장은 면접 본다고 하면 입장 가능하다고 하심. 야외 주차장은 일찍 도착해야 주차 가능함(자리 공간 부족). 면접은 보통 10분 간격임. 면접관님들은 총 세 분으로 그 중에서 가운데에 계신 분이 학과장 교수님으로 학과와 관련된 세특 얘기를 많이 물어보심. 나머지 두 분께서는 지원동기, 마지막으로 할 말, 개인능력치 관련 질문 등 공통 질문을 물어보심. 꼬특이사항리질문은 별로 안하시는데 활동 개념에 대해서 많이 물어보심. 생기부 기반이다보니 어려운 내용이 있으면 쉽게 풀어서 설명해주시고 구체적으로 질문하심. 끝나기 전에 노크 소리가 은근 신경 쓰이는데 소리에 예민한 사람이라면 모의면접때 미리 준비하는 것도 나쁘지 않을 것이라고 생각함.합/불 분석최초합꼬리질문에 대처하지 못한 것에 대해 아쉬움. 압박 질문이라기보다는 심화 질문들을 물어보셔서 생각보다 더듬어서 말한 것 같아 아쉬움. 실험관련 내용들을 많이 준비해갔는데 개념 아쉬운 점질문을 많이 하심. 면접이 끝나기 전에 밖에서 노크를 하시는데 미리 공지를 받았으나 긴장해서 준비했던 마지막 할 말을 제대로 말하지 못함."}],"naesin":"2.79","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형(O) 【1단계】 서류 100 (5배수) 【2단계】 서류 50, 면접 50","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"자율전공학부","jeonhyeong":"학생부종합/지역인재","method":"생기부 기반 면접 / 대기반에서 기다린후 면접함","notes":"","qa":[{"q":"간단하게 지원동기부터 들어볼게요.","a":"저는 가천대학교 자율전공학부에 지원하게 된 이유는 저의 학업과 진로를 스스로 설계할 수 있는 기회를 얻고자 지원하게 되었습니다. 저는 여러 과목에 대한 흥미를 느끼며 다양한 분야에 대한 지식을 쌓아왔습니다. 특히, 교육과 인문학 그리고 사회문제에 대해 관심이 많았고, 이러한 다양한 관심사를 바탕으로 융합적 사고를 기르고 싶었습니다. 가천대학교 자율전공학부는 여러 교양수업을 탐색할 수 있는 환경을 제공하여, 저의 적성과 흥미를 발견할 수 있는 최적의 장소라고 생각합니다. 저는 자율전공학부에서의 학습을 통해 제 미래의 진로를 명확히 하고, 사회에 긍정적인 영향을 미치는 인재로 성장하고 싶습니다. 이러한 이유로 지원하게 되었습니다."},{"q":"자율전공의 들어와서의 학업계획은?","a":"저는 원래 교육을 희망을 했던 학생이었습니다. 최근에 미디어가 많이 사용되어 비대면수업을 많이 하는 것으로 알고 있습니다. 비대면 수업에서는 학생들의 말이나 행동 등 대면수업과 달리 전달하기 까지의 딜레이와 같은 불편한 문제가 있다고 생각합니다. 미디어커뮤니케이셩학과에서 미디어관련 지식을 배우고난후 이러한 불편한점을 해결하는 매체를 한번 만들어 보고싶습니다."},{"q":"3학년 고전과 윤리 수업에서의 롤스의 정의론을 설명했다고 하셨는데 롤스의 정의론에 대해서 어떻게 생각하십니까?","a":"존 롤스의 정의론은 정의를 사회 제도의 가장 기본적인 덕목으로 간주하며, \"공정으로서의 정의\"라는 개념을 제시합니다. 롤스는 두 가지 정의의 원칙을 제시합니다. 그는 정의를 원초적 입장과 무지의 베일이라는 가설적 상황을 통해 논의합니다. 이는 효율섣과 평등의 균형을 강조하녀 현대사회에서는 필요하다고 느낍니다"},{"q":"3학년 문학과 매체시간에서 해바라기라는 시를 만들었는데 어떤 내용을 담고 있나요?","a":"해바라기는 해를 따라 움직이는 특성과 항상같은 방향으로 바라보는 특성이 있습니다. 이러한 특성들로 희망 열정, 변치않은 사랑이나 충성의 대한 내용을 담고 있습니다."},{"q":"가장 인상깊게 읽은 책이 있습니까?","a":"저는 지혜로운 교사는 어떻게 말하는가 가라는 책이 가장 기억에 남습니다. 이 책은 다양한 말하기 방법으로 수업에 적용하는 내용들이 있습니다. 하지만 결국 이것도 대면수업에서 효과적이고 비대면수업에서의 효과는 떨어질 것이라고 생각 했습니다. 저는 여기서 비대면 수업에서도 대면수업처럼 효과적이려면 어떤 좋은 방법이 없을까 하고 의문을 품게되는 계기가 되었습니다. 그래서 자율전공학부의 들어가 다양한 기초지식과 미디어 관련 지식을 쌓아 매체를 한번 만들어 보고싶습니다."},{"q":"매체를 만든다고 하셨는데 혹시 어떤식으로 구성할 것인지 생각 했습니까?","a":"저는 아직 미디어나 기초관련 지식들이 부족하다고 생각합니다. 그리하여 저는 가천대학교 자율전공학부의 입학하여 지식을 쌓아 올린 후 구성할 것입니다."},{"q":"짧은 시간이었지만 면접의 응해 주셔서 감사합니다. 마지막으로 하고싶은 말이 있나요?","a":"면접관님 늦은 시간까지 저포함하여 많은 학생들을 면접하느라 고생이 많으십니다. 그럼에도 제 이야기를 끝까지 들어주셔서 감사합니다. 저는 합격후 매체를 만들어 낼 수 있는 인재로 성장하고 싶습니다.많은 학생이 면접에 응시하기 때문에 면접시간이 많이 짧음(8~9분 정도?)특이점면접관님 3분이 계셧고 면접분위기는 긴장을 해도 풀어주실려고 하시고 엄청 좋았습니다.합/불 분석아쉬운 점"}],"naesin":"1.0","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( 0 ) 【1단계】 서류100(7배수) 【2단계】 서류50+면접50","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"컴퓨터공학과","jeonhyeong":"학생부종합전형/기회균형전형","method":"기회균형전형(학생부 70%, 면접30%) / 1명당 10분, 면접관 3명과 질의응답 형식","notes":"교과 내용 잘 숙지해야 합니다.","qa":[{"q":"지원동기부터 간략하게 말씀해 주세요.","a":"안녕하십니까, 저는 백엔드 프로그래머를 지망하는 가번호 44-5번 학생입니다. 전 블록 코딩으로부터 흥미를 느끼고, 고등학교 진학 이후 언어를 실제로 다뤄보며 확신을 가지게 되었습니다. 세상을 밝히는 프로그래머가 되고자 가천대학교 컴퓨터공학부에 지원하게 되었습니다."},{"q":"가천대학교 사이트에 들어가 보신 적 있나요?","a":"네, 있습니다. 그곳에서 제 최근 관심 분야인 AI에 대해 3가지 심화전공 트랙으로 구분하여 수업을 진행한다는 것을 보게 되었습니다. 그래서 가천대학교에 지원한 것도 있습니다."},{"q":"가천대학교를 선택하는 데에 있어 교과 과정도 잘 들어맞았던 거네요? ( 웃으며 )","a":"네네 그렇습니다. ( 웃으며 )"},{"q":"3년간 배운 교과목들 중, 컴퓨터공학과 가장 관련 있는 과목이 뭐라고 생각하시나요?","a":"AI와 관련지어 말씀드리자면, 선형대수학이나 함수해석학 같은 내용이 필수적이라는 글을 읽었습니다. 따라서 여러 미적분 개념이나 다양한 프로그래밍 분야에서 수학이 가장 중요하다고 생각합니다."},{"q":"수학교과 세특을 읽어보니 확통과 프로그래밍이 관련 있다고 적혀있는데 예시를 들어주실래요?","a":"게임에 보시면 뽑기라는 기능이 있습니다. 이를 구현하는 데에 있어 확률과 통계가 꼭 필요합니다. 확률을 조정함으로써 등급을 조정하고, 등급을 세세하게 나눌 수도 있습니다. 강화와 같은 기능에도 이를 사용할 수 있습니다."},{"q":"문제 하나 낼게요. y=IxI를 미분할 수 있나요?","a":"원점에서 뾰족한 점이 발생하기 때문에 미분이 불가능한 것으로 알고 있습니다."},{"q":"정적분과 부정적분의 차이를 아시나요?","a":"정적분은 일정 범위내에서 적분하여 넓이나 적분값을 구하는 데에 이용할 수 있고, 부정적분의 경우 주어진 식을 적분만 하는 개념이라 알고 있습니다."},{"q":"삼각함수의 특징 여러가지중 몇가지 저희에게 소개해주실수 있나요?","a":"sin함수 그래프는 원점대칭, cos함수 그래프는 y축 대칭, tan함수 그래프는 원점 대칭입니다. 또한, sin과 cos은 2파이라는 주기를 가지고 있으며, tan는 1파이 입니다."},{"q":"시간이 다 되었는데, 마지막으로 하고 싶은 말씀 있으면 간략하게 해주세요.","a":"3년간 정말 다양한 활동들을 많이 했습니다. 동아리를 포함해서 정말 다양하게 준비했었는데 이들을 말씀드리지 못하게 되어 정말 아쉽습니다. 하지만 가천대학교 컴퓨터공학과에 오게 된다면 제 역량을 확실히 보여드리겠습니다. 감사합니다!면접관 3명이 앉아 질문하고, 반대편에 학생이 앉아서 면접을 진행함. 학생 의자 앞에 책상특이점이 있음.합/불 분석최초합아쉬운 점예상 질문과는 전혀 다른 교과 개념에 대한 내용이 주를 이뤄 아쉬웠던 면접입니다."}],"naesin":"","result":"","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( O ) 【1단계】 서류 100% 【2단계】 학생부 70%, 면접 30%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"클라우드공학","jeonhyeong":"학생부 종합 / 바람개비 전형","method":"서류확인면접 / 일반적인 질문과 답변","notes":"","qa":[{"q":"드론의 pid제어 시스템에 대해 탐구하셨다고 했는데 pid제어 시스템에 대해 설명해주세요.","a":"pid제어 시스템은 드론의 균형을 센서로 제어함- 도서 아두이노 입문을 통한 드론 제어를 참고하여 pid제어 시스템을 탐구 및 직접 구현함."},{"q":"학과 지원 동기","a":"어릴떄부터 과학상자 만들기 등 과학에 대한 관심을 가지고 있었고 아두이노 동아리에 들어가 sw 소프트웨어에 대한 자신의 지식을 심화하였고 가천대가 sw 중심대학으로 선정 되었다는 사실을 알게된 후 학과에만 있는 two track제도에 흥미를 가지게 되어 지원하게 되었습니다."},{"q":"학과에 지원하기 위해 한 노력","a":"이 학과에 지원하기 위해서는 소프트웨어에 대한 기본적인 지식을 갖춰야 한다고 생각하여서 프로그래밍 언어 교과서를 독학하였고 학교 과목중 프로그래밍에 대해 전문적으로 배울 수 있는 과목이 없어서 공동온라인 교육과정에서 프로그래밍 과목을 신청하여 이수받았습니다.이후에 코딩을 이용하여 창작물을 만드는 경험을 쌓고자 아두이노 동아리에 차장으로 들어가 매트릭스를 이용한 게임과 cad설계도를 통해 자동차 스티어링을 설계하는 등의 활동을 하였습니다."},{"q":"c언어와 파이썬 언어의 차이점에 대해 설명해주세요.","a":"c 언어는 시스템 프로그래밍이나 고성능 애플리케이션 설계를 할 때 주로 사용되고 파이썬은 웹개발, 데이터 과학, 머신러닝 등 광범위한 분야에 주로 사용됩니다. 큰 특징으로는 c언어는 정적 타입 언어로 변수의 타입을 명시해야 하는 반면에 파이썬은 동적 타입의 언어로 변수를 따로 명시할 필요가 없다는 큰 차이점이 존재합니다."},{"q":"본인의 장점과 단점은 무엇이고 단점을 보완하기 위해 노력한 것이 있다면 설명해주세요.","a":"저의 장점은 창의력 높고 목표 의식이 분명한 점입니다. 저는 무엇인가를 하는 의지와 목표가 분명해진다면 그것을 성취하기 위해서 최선을 다합니다. 저의 단점은 동시에 여러 가지 일이 어렵다는 점이 있습니다. 그럼에도 저는 공학 도구툴을 사용하여 속도적인 측면에서의 저의 단점을 보완 해왔습니다. 또한 저는 일정 시간을 두고 그 안에 일을 마무리 지을 수 있는 능력을 키우고자 각각의 일마다 시간을 할당하는 타임 블록 기법을 사용하여 저 스스로 꾸준히 단점을 보완해 나가고 있습니다.특이점합/불 분석최초합아쉬운 점"}],"naesin":"2.5","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형( ) 【1단계】 서류100(5배수) 【2단계】 1단계 50+면접50","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"화학과","jeonhyeong":"학생부종합/농어촌","method":"생기부 기반 면접 1. 면접 대기실 이동 2. 본인 차례가 되면 면접 방 이동 3. 면접 시 유의사항 / 안내 4. 면접 진행 가천대 아이스 브레이킹 타임 있다고 들었었는데 바로 면접 진행함. 면접관 3명","notes":"중 1명은 계속 말하는 것 끝부분마다 꼬투리 잡아서 질문함. 압박 면접의 느낌이 살짝 들었음.","qa":[{"q":"학과 지원 동기와 본인이 졸업 후 무엇을 하고 싶은지 말해보세요.","a":"제가 화학과에 진학하게 된 계기는 근본적으로 화학이 좋아서입니다. 화학을 좋아하게 된 계기는 고등학교 1학년 통합과학 시간에 화학 관련 문제를 풀다 흥미를 느껴서입니다. 이후 화학1, 2과목을 이수하면서도 흥미를 가졌고, 성적도 잘 따라오다보니 더 관심을 기울일 수 있었고 이에 따라 대학에 진학해서도 화학을 공부하고 싶다고 느꼈습니다. 졸업 후에는 국가 기업의 화학 연구원이 되고 싶습니다."},{"q":"화학 연구원이라하면 구체적으로 어떤 것이 있는지 예시를 들어볼래요?","a":"예를 들어 화장품 관련도 있을 것이고...(갑자기 말 끊으심)"},{"q":"그럼 본인은 화장품 쪽에서 일할 건가요?","a":"아뇨 그냥 예시를 든 것뿐입니다."},{"q":"고등학교 1학년 통합 사회 시간에 염화칼슘 관련해서 보고서 작성하셨는데, 염화칼슘이 눈을 녹이는 원리가 무엇인가요?","a":"염화칼슘은 눈의 어는점을 낮추어 눈이 애초에 얼지 않도록 하는 것이라고 알고 있습니다."},{"q":"3학년 동아리 시간에 카페인 추출 실험하셨는데 실험 과정을 얘기해주세요.","a":"물과 카페인, 탄산칼슘을 넣고 가열한 다음 분별 깔때기에 넣어서 탄산칼슘을 걸러내고 다이클로로메테인을 넣어 카페인을 추출합니다."},{"q":"2학년 화학 시간에 암모니아 분수 실험하셨는데 실험 과정 얘기해주세요.","a":"암모니아수를 가열하고 포집된 기체를 둥근 플라스크에 넣고 페놀프탈레인 용액이 든 스포이드를 안에 넣어서 분수를 관찰합니다."},{"q":"암모니아 말고 다른 것으로는 진행이 안 되나요?","a":"(예상 못 한 질문이라 당황) 없는 것으로 알고 있습니다."},{"q":"1학년 통합과학 시간에 알칼리 금속에 관하여 탐구하였는데 알칼리 금속이 뭔가요?","a":"알칼리 금속이란 주기율표 상에서 수소를 제외한 1족 원소입니다."},{"q":"알칼리 금속에서 알칼이 의미하는 바가 무엇이길래 그렇게 명명을 한 건가요?","a":"(모르겠어서 뜸 들임) 잘 모르겠습니다. 진학하면 더 열심히 탐구~ (뻔한 레파토리)"},{"q":"3학년 화학 시간에 황산구리 몰 농도 제조하셨는데 실험 과정 설명해볼래요?","a":"먼저 황산구리를 비커에 물과 함께 넣어 녹이고 부피 플라스크에 수용액을 넣은 다음 표시선까지 맞춰 물을 넣어줍니다. (노크 소리 남) 그 이후에 파라필름으로 부피 플라스크의 입구를 막아 양손으로 끝을 잡고 위 아래로 흔들어주어 섞어줍니다."},{"q":"네. 질문은 여기까지입니다. 마지막으로 하고 싶으신 말 있으시면 하시고 고생 많으셨습니다.","a":"저는 어렸을 때부터 나눔을 강조 받으며 자라왔습니다. 이 학교의 교육 이념을 찾아보니 나눔을 협업하는 실천인이 되자는 문구를 보았습니다. 그래서 제 꿈을 향한 첫 발걸음을 가천대학교로 하고 싶다는 생각이 들었습니다. 꼭 이 학교에 진학해서 제 비전을 누리고 싶습니다. 감사합니다. 수고하셨습니다.특이점면접은 약 10분간 진행되고 입장 퇴장 시 말고는 분위기가 좀 딱딱했음. 합/불 분석아쉬운 점준비했던 것보다 면접을 너무 못 본 것 같아서 아쉽다."}],"naesin":"3.65","result":"불합격","resultNote":"최초후보순위","suneung":"","type":"일괄합산( ) 단계형( O ) 【1단계】 서류100 【2단계】 면접50+1단계50","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"회계세무학과","jeonhyeong":"학생부종합/가천바람개비","method":"확인면접 시청각실 같은 곳에 한 과 당 10명 씩 모아둠. / 순서가 되면 1번부터 따로 부르고, 면접고사장 앞에 있는 책상에서 잠깐 대기","notes":"전자기기 다 전원 끄기","qa":[{"q":"(시간이 없어서 중간에 말 끊을 수도 있어요.) 먼저 학과 지원 동기부터 말해주세요?","a":"저는 1학년 통합사회 시간에 왜 세계화가 문제일까를 읽고 기업의 경영과 활동에 관심을 가졌습니다. 그러다가 3학년 자율활동 시간에 환경, 지속가능한 발전 교육에서 환경 보호 실천 방법으로 ESG에 대한 소개를 듣고 지속가능한 사회를 위한 ESG 공시 의무화에 대해 ~~~~~ 목표를 세우게 되었고 지원하게 되었습니다."},{"q":"방금 지원 동기에서 말했던 ESG 활동 중에서 인상 깊었던 부분 말해주세요?","a":"활동을 하며 기사를 찾아보니 기업이 ESG에 반대하는 가장 큰 이유는 ESG에 대한 전문성을 갖춘 회계사가 부족하다는 부분이였습니다. 이 부분이 저는 가장 인상깊었습니다. 그리고 저는 ESG에 대한 전문성을 갖춘 회계사가 되고 싶다고 생각했습니다."},{"q":"미적분에서 자연상수 e가 무엇인가요?","a":"n의 값이 무한히 커질 때 1+n 분의 1의 n제곱이 2.718 정도의 수에 가까워지는데 이것을 e라고 합니다."},{"q":"그러면 e는 왜 사용하나요?","a":"미적분에서 함수의 극한 값을 ~~."},{"q":"그러면 e의 엑스제곱을 미분하면 얼만지 알아요?","a":"똑같이 e의 엑스제곱입니다."},{"q":"(웃으며) 미적분에서 e를 미분하는 이유는 뭐예요?","a":"그 부분까지는 잘 모릅니다."},{"q":"확률과 통계에서 정규분포를 표준정규분포로 변환하는 이유는 뭐예요?","a":"정규분포의 확률변수 a와b의 평균과 표준편차가 너무 차이가 나서 표준정규분포로 변환하고 변환하면 평균이 0, 분산이 1이라고 비교하기 편해집니다."},{"q":"아하, 그러면 표준정규분포로 변환하는 과정은 알아요? 잘 모르나?","a":"(웃으면서) 네, 그것도 잘 모르겠습니다."},{"q":"수학과제탐구에서 per이 뭔지 알아요?","a":"네, 기업이 시장에서 매매되는 가격이 연 순이익의 몇 배인지를 표현한 지표입니다."},{"q":"그러면 per 은 어떨 때 사용되는지도 알아요? 여기까지는 탐구를 안 해봤나요?","a":"네, 잘 모르겠습니다."},{"q":"사회문제탐구에서 분식회계의 사례를 하나 얘기 해줄래요?","a":"저는 D사 자동차의 사례를 들었습니다. 이 기업이 매출액을 높이고 비용을 줄여 재무제표를 공개했다가 결국에는 걸려서 파산했던 사례를 들었습니다."},{"q":"학교생활 중 본인이 갈등을 해결한 사례가 있나요?","a":"3학년 미적분을 통한 경제학적 시선 넓히기 활동에서 주식투자를 잘 모르고 관심 없어하는 모둠원이 있었는데 주식투자가 무엇인지 설명하고 저만의 투자전략을 세워서 친구에서 설명해주며 이를 참고해서 모둠원의 투자전략을 세울 수 있도록 도왔습니다. 그래서 이후 활동에 적극적으로 참여할 수 있게 되었습니다."},{"q":"마지막 하고 싶은 말 하세요?","a":"저는 책임감과 정확성이 강한 학생입니다. ~~~~. 감사합니다.꼬리질문, 압박면접이 심합니다. 웃으시면서 꼬리질문을 하십니다. 그리고 시간이 부족하고 특이점면접관이 세 분이나 계셔서 정신이 없고 답변을 빨리 못하면 “아 이건 몰라요?” 라고 먼저 말씀하십니다. 그래서 생각할 시간이 부족합니다.면접에서 자신의 스토리를 잘 말할 수 있도록 큰 그림을 먼저 그렸습니다. 큰 그림을 그리합/불 분석고나니 나머지 소소한 것들은 그 큰 그림에 들어오게 되어서 정리가 잘 되었습니다. 실제 면접 상황을 염두해두고 상상해보면서 말로 표현하는 연습을 계속 하였습니다.처음에 면접고사장에 들어갔을 때 ‘시간이 부족해서 말을 끊을 수도 있다’고 하시길래, 그 아쉬운 점때부터 답변을 빨리 빨리 해야지하는 생각에 초조했고, 빨리 말해야 될 것 같은 압박감이 생겨서 말 끝을 정확하게 맺지 못한 것이 아쉽습니다.<가톨릭학교 학생부종합전형 면접 평가 안내><출처 : 2025학년도 가톨릭대학교 학생부종합전형 가이드북>"}],"naesin":"","result":"최초합격","resultNote":"최초후보순위","suneung":"최저기준없음","type":"일괄합산( ) 단계형(○) 【1단계】 5배수 【2단계】 면접 50% 전단계성적 50%","src":"경상남도교육청 「2026 대입 면접 전략 자료집(학생부 기반)」","year":"2025학년도"},{"univ":"가천대학교","dept":"간호학과","jeonhyeong":"학생부종합(농어촌(종합))","method":"생기부 기반 면접 / 면접시간 10분 / 면접위원 3명","notes":"면접 초반 긴장을 풀 만한 가벼운 질문을 주심. · 압박 면접 분위기는 아님. · 면접 내내 미소 지으면서 지원자 눈을 계속 쳐다보심.","qa":[{"q":"간단한 자기소개와 지원동기를 말씀해주세요.","a":"환자가 병원에서 홀로 지내야 해서 의지될 사람이 없을 때, 가천대학교의 교육이념인 애국, 봉사, 박애의 정신으로 환자에게 제 손길이 따뜻한 위로와 힘이 되고자 합니다."},{"q":"왜 다른 학교가 아닌 가천대학교에 지원했나요?","a":"영어 활동 중에 국경없는 의사회를 탐구했던 활동이 있었습니다. 이 활동에서 종교, 인종 등에 관계없이 치료하는 모습을 보고 진정한 봉사 정신이 무엇인지 깨달았습니다. 가천대학교의 교육이념 중 봉사 정신을 가천길병원에서 실현하고자 지원하게 되었습니다."},{"q":"2학년 동아리 활동에서 당뇨병에 대해 탐구한 게 있는데 설명해주세요.","a":"제1형 당뇨병과 제2형 당뇨병이 있습니다. 제1형 당뇨병은 이자의 베타 세포에서 인슐린이 전혀 생산하지 못해 발생하고 제2형 당뇨병은 인슐린 저항성이 커져서 인슐린의 작용이 원활하지 않아 발생합니다."},{"q":"인슐린이 무슨 역할을 하나요?","a":"우리 몸의 혈당이 증가하면 이자에서 인슐린 분비가 촉진되어 혈당을 낮춰주는 역할을 합니다."},{"q":"생기부에서 존엄한 죽음과 호스피스라는 단어가 많이 보이는데, 지원자가 생각하는 존엄한 죽음이 무엇인가요?","a":"죽음의 문턱에서 환자 스스로 자기결정권을 행사하는 것이 존엄한 죽음이라고 생각합니다. 또한, 환자와 환자의 가족 모두 마지막 순간이 고통스럽고 힘든 기억이 아니라 그동안 경험했던 행복한 추억이 머릿속을 스쳐 지나가며 삶을 마무리할 수 있었으면 좋겠습니다."},{"q":"사전연명의료의향서와 연명의료 결정제도가 무엇인지 설명해주세요.","a":"사전연명의료의향서는 마지막에 본인이 표현할 수 없을 때를 대비해서 자신의 의사를 미리 밝힐 수 있는 문서입니다. 19세 이상의 성인이 등록 기관에 가서 본인이 직접 써야 합니다. 연명의료 결정제도는 말기 암환자 등 임종기간에 놓인 환자가 본인의 의향에 따라 연명의료를 시행하지 않거나 중단할 수 있는 제도입니다."},{"q":"수학과제탐구에서 혈류 속도와 혈류량에 대한 탐구를 9회에 걸쳐 진행했다 했는데 설명해주세요.","a":"푸아죄유는 혈액이 혈관을 따라 흐를 때, 저항은 혈관의 반지름이 클수록 작아진다는 점을 이용해 저항에 관한 식을 확립하였습니다. 이 방정식에서 반지름을 미분하면 반지름에 대한 속도의 변화율을 구할 수 있으므로 혈류 속도를 알 수 있습니다. 혈류량은 혈관의 반지름의 네제곱에 비례하므로 혈관의 단면적을 구해 적분하면 알 수 있습니다."},{"q":"과학과제연구에서 토양 속 균주에 대해 실험과정을 설계하고 진행했다 하였는데 어떤 실험이었나요?","a":"토양 속에 존재하는 유익균인 아스펠리우스가 존재한다는 사실을 알고 실험을 진행했습니다. 말토오스, 갈락토오스, 포도당을 이용해 배지를 만들고 그 위에 토양현탁액을 뿌려 관찰했습니다. 하지만, 원했던 아스펠리우스 균이 아닌 아스펠리우스 계열의 다른 균을 발견할 수 있었습니다."},{"q":"나중에 어느 곳에서 일하고 싶나요?","a":"아직 어느 곳에서 일하고 싶은지는 정해지지 않았습니다. 하지만, 어느 곳에서 일하든지 간에 덧셈, 뺄셈, 곱셈, 나눗셈을 실천하는 간호사가 되겠습니다. 첫째, 환자 중심 간호에 타인을 배려하는 따뜻한 마음을 더하겠습니다. 둘째, 수동적인 자세는 빼고 적극적으로 환자를 돌보겠습니다. 셋째, 열정을 곱해 끊임없이 발전하는 간호사가 되겠습니다. 마지막으로 환자들에게 희망과 사랑을 나누는 간호사가 되겠습니다."},{"q":"마지막으로 할 말 있나요?","a":"간호사는 무엇보다 환자와의 친밀감 형성과 의사소통이 필수적이고 중요합니다. 가천대학교에 입학하여 ‘의사소통과 인간관계의 실제’라는 과목을 수강하여 효과적인 의사소통 방법이 무엇인지 배우고 싶습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"간호학과","jeonhyeong":"학생부교과(지역균형)","method":"생기부 기반 면접 / 면접시간 10분~15분 / 면접위원 3명","notes":"남자분은 안내사항만 말씀하시고 질문 안하심 · 면접분위기는 생각했던 것 만큼 딱딱하지는 않았지만 그래도 긴장됐음 · 대기하는 곳에서 8명정도 같이 있다가 면접실로 한명씩 들어감.","qa":[{"q":"지원동기","a":"저는 꿈이 많은 학생이었습니다. 그래서 정확한 진로를 확정하는데 어려움도 겪고 방황도 많이 했는데 처음으로 정하게 된 꿈은 자기가 아픈 부위를 정확하게 말로 전할 수 없는 동물들을 보살펴주고 치료해주고 싶다는 생각을 하게 되었습니다. 그러던 중 2 3학년 때 반장활동을 하며 친구들을 한명도 소외되지 않도록 챙겨주고 보살피는 과정에서 내가 치료하고 보살피고 싶은 대상이 사람이어도 적성에 잘 맞을 것 같다는 생각이 들었고 간호사라는 직업에 관심이 생겼고 간호사가 되고 싶어졌습니다. 그래서 가천대학교 간호학과에 지원하게 되었습니다."},{"q":"가천대여야 하는 이유?","a":"가천대학교의 교육이념이 박애 봉사 애국으로 알고있음 그런데 나의 가치관이 힘들고 어려운 사람이 있으면 그들에게 희망과 기쁨을 주고 봉사하고 또한 미래 세대를 위한 토대와 길을 잘 닦아주자였기 때문에 나의 가치관과 정말 잘 맞는다는 생각이 들어서 가천대학교에 지원하게 됨(미리 교육이념 외워감)"},{"q":"캠공에서 했던 탐구들 간호사에 적용시킨다면?","a":"캠공에서 진행했던 활동이 강아지가 치매에 걸렸을 때 ct를 찍어보면 정상과 다른 뇌구조를 갖게 된다고 함 그래서 그 사실을 바탕으로 인공지능에 치매에 걸린 강아지의 여러가지 뇌사진을 학습시켜놓으면 인간이 굳이 판단하지 않아도 인공지능이 알아서 치매인지 아닌지를 구분하게 하는 의료 ai를 계획했었는데 만약 인간도 치매에 걸렸을 때 정상과 다른 뇌모양이 형성된다면 여러가지 사례들을 인공지능에 학습시켜 의사가 개입하지 않고 간호사의 판단만으로도 빠른 질병의 판단이 가능할 것 같다(이 부분도 약간 준비했었음)"},{"q":"생명과학실험선생님께서 생기부를 잘써줬는데 그중에서 기억에 남는 실험","a":"갈락토스 수용액과 효모액을 섞었을 때 알콜발효가 잘 일어나는지 관찰하는 실험이었는데 처음 실험을 진행했을 때는 제대로 되지 않음. 그래서 빠르게 상황판단을 하고 했던 실험을 복기해보는 과정에서 문제점을 찾아냄. 관이 넘칠까봐 정해진 효모액을 다 넣지 않았다는 점과 적정 온도를 유지하지 못하였다는 점을 알게 되었고 이 부분을 보완하고 수정해서 재실험을 했을 때 원하는 결과가 잘 나와서 굉장히 기억에 남았다."},{"q":"간호사에도 여러가지 종류가 있는데 어떤 간호사가 되고 싶은지-소아병동 간호사","a":"자신이 아픈 부위를 정확하게 말로 표현하지 못하는 영아를 치료하고 돌보는 소아병동의 간호사가 되고 싶다.Q5-1: 소아병동 간호사가 지녀야 할 자세최근 유튜브에서 소아중환자실 간호사 관련 영상을 본 적이 있다. 그 영상에서 간호사님께서 수술이 끝난 아이에게 이름을 불러주며 다정한 말로 인사해주고 계속해서 긍정적인 말과 꼼꼼한 케어를 해주셨는데 그 영상을 보고 정말 감동을 많이 받았다. 그래서 소아병동 간호사는 영상 속의 간호사처럼 계속 긍정적인 말을 해주고 환자에게 사랑을 쏟으며 꼼꼼한 케어까지 해주는 자세가 필요하다고 생각한다."},{"q":"생명과학과 수의사에 관련해 많은 탐구를 했는데 거기서 깨달은점(질문이 너무 어려웠나?라고 하심)","a":"지금까지 했던 탐구들을 생각해보면 생명체가 어떻게 움직이고 기능하는지 등 기초적인 부분부터 윤리적인 가치까지 생명체 전반에 대해 탐구하고 있었다는 것을 깨달았다.(당황해서 얼렁뚱땅 답변함)"},{"q":"마지막으로 하고 싶은 말","a":"지금까지 제 말을 경청해주셔서 감사드리고 가천대 간호학과에 진학 후 전문적인 지식을 쌓아 간호사가 되었을 때 지금 배운 경청의 자세와 전문적인 간호지식을 가지고 환자를 잘 보살피고 치료하는 간호사가 되도록 하겠습니다. 감사합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"","jeonhyeong":"학생부종합(가천AI·SW)","method":"면접시간 10분 / 면접위원 3명","notes":"생활기록부에서 전공 관련 탐구 내용에 대해 예상보다 많이 질문했음. 전공 관련 탐구 내용은 구체적으로 답할 수 있도록 준비하는 것이 중요함.","qa":[{"q":"(3학년 창체 진로) 퍼셉트론에 대해 발표했는데 발표 내용과 느낀점은?","a":"퍼셉트론은 뇌의 학습 기능을 모델화한 알고리즘입니다. 퍼셉트론은 여러 신호를 입력받아 하나의 신호로 출력하고 입력층과 출력층으로 이루어져 있습니다. AND, NAND, OR 세 가지 논리 회로를 구현할 수 있습니다. 저는 3학년 때 ‘인공지능과 파이썬’과 관련된 책을 읽고 퍼셉트론에 대해 탐구한 내용을 발표했는데, 그중에서도 특히 다중 퍼셉트론으로 XOR 값을 출력해내는 과정이 인상깊었습니다. 저는 AND, OR, NAND를 활용하여 파이썬으로 XOR 함수 직접 만들어보고 그 과정을 발표했습니다. 저희 반 친구들 중에 컴퓨터 프로그래밍에 관심이 있는 친구들이 많은데, 이 친구들을 대상으로 다중 퍼셉트론으로 XOR 함수를 푸는 과정을 직접 설명해주며 지적 희열을 느꼈습니다."},{"q":"(2학년) 확률과 통계 과목을 배웠는데 순열과 조합의 의미는?","a":"순열은 서로 다른 n개 중 r개를 뽑아 순서에 맞게 나열할 수 있는 가지 수를 의미합니다. 조합은 서로 다른 n개 중에서 r개를 뽑아 그룹을 만들 때, 만들 수 있는 그룹의 가지 수를 의미합니다. 이때 순열과 조합의 차이는 ‘순서’라고 할 수 있습니다. 조합은 순열과 달리 순서가 중요하지 않고 뽑으면 끝인 반면에 순열은 같은 그룹 안에서도 어떤 순서로 나열하는가에 따라 가지 수가 더 다양해질 수 있습니다. 음식점에서 메뉴를 고를 때 메뉴판에서 3가지의 요리를 단순히 고르를 것을 조합이라고 한다면, 순열은 3가지 요리가 나오는 순서까지도 결정하는 방법의 수라고 말할 수 있습니다."},{"q":"(3학년) 블록체인이 무엇인가?","a":"블록체인은 블록을 연결했다는 의미로, 가상 화폐로 거래할 때 해킹을 막기 위한 기술을 의미합니다. 여기서 블록은 일정 시간 동안 거래 내역이고, 승인된 거래 내용이 담긴 블록이 네트워크에 있는 사람들에게 전송됩니다. 가상화폐인 비트코인 또한 블록체인을 기반으로 한 기술입니다."},{"q":"해시함수가 무엇인가?","a":"임의의 길이를 갖는 데이터를 데이터 길이에 상관없이 항상 고정된 크기의 값으로 변환해주는 함수입니다."},{"q":"3학년때 반장을 했었는데 자신의 어떤점 때문에 반장이 될 수 있었던 것 같나요?","a":"저의 소통 능력과 리더십 때문이라고 생각합니다. 저는 1, 2학년 때 직접 친구들을 섭외해 밴드부를 만들었고, 밴드 부장을 맡아 학년 말 학교 축제에서도 공연 기회를 만들었으며, 여러 갈등 상황에서도 동아리원들이 소외감을 느끼지 않고 서로 화합하도록 이끌어서 무대를 성공적으로 마친 경험도 있습니다. 이런 저의 자질을 지켜본 친구들 덕분에 반장이 될 수 있었다고 생각합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"경영학부","jeonhyeong":"학생부종합(가천바람개비)","method":"면접시간 약 8분 / 면접위원 3명","notes":"","qa":[{"q":"(자기소개x 지원동기x) 고등학교 3년 동안 가장 유의미한 경험을 이야기해주세요.","a":"'학생회 학교 밖 매점 제휴사업'입니다. 먼저 교내 학생들의 선호가 높은 상점을 조사하고 그 상점을 위주로 제휴 계약을 맺었습니다. 이 사업이 상점 입장에서는 학생들에게 충분한 홍보가 가능해, 시장에서 경쟁력 있는 상점으로 나아갈 수 있다는 점, 학생 입장에서는 평소에 선호하는 상점에서 추가 할인을 받을 수 있다는 점에서 양측에게 긍정적인 결과를 만들어냈습니다. 이 활동이 유의미했던 이유는 제가 학생 신분임에도 사회문제를 직접 해결할 수 있었던 경험이었기 때문입니다. 당시 코로나로 지역 상권이 침체되어있다는 것을 인식했고 학교와 상점의 계약을 통해 문제를 해결할 수 있었습니다. 이후 많은 학교들이 저의 사업을 벤치마킹했고, 사업은 다른 학교 상권까지 확장되었습니다. 저의 사업이 최종적으로 시 전체에 미친 긍정적 영향을 보고 사회적 기업가라는 꿈을 가지게 되었고, 경영학이 문제 인식과 해결의 실질적 연결점 역할을 할 수 있다는 점을 배웠습니다."},{"q":"제휴사업을 힘-의존이론과 쌍무적억제이론으로 재분석했는데 이것에 대한 정의와 어떻게 재분석했는지 설명해주세요.","a":"힘-의존이론은 ~~ 이고 쌍무적억제이론은 ~~입니다. 상호간 계약의 문제에서 발생하는 현상을 다룬 이론이기 때문에 제휴계약을 맺는 과정을 힘-의존 이론을 사용해서는 ~~하도록 쌍무적억제이론을 통해서는 ~~~이러한 재분석 결과를 도출했습니다."},{"q":"수학에 게임이론이 있는데 설명 가능할까요","a":"죄수의 딜레마 게임은 많이들 알고 계실거라 믿어 기업게임을 소개해드리고 싶은데 괜찮을까요? 기업게임은 기업끼리 상호간 영향을 주기 때문에 각 기업이 어떤 고가전략과 저가 전략을 선택하냐에 따라 시장 전체의 보수가 올라가거나 줄어든다. 하지만 각 기업은 타 기업이 어떤 전략을 선택할지 몰라 본인의 기업의 현재 상황에서 가장 높은 보수를 얻을 수 있는 전략을 선택한다는 이론입니다."},{"q":"경제 관련 활동이 많은데 경제 관련 키워드 좀 물어봐도 될까요? 첫 번째 기준금리 누가 올리나요?","a":"중앙은행이라고 답함. 한국은행이었음. 그래서 혹시나 틀렸다면 이러한 지식을 보완해서 입학할 수 있도록 공부한다고 함.Q4-1: 한국의 금리는 오르고 있나요? 내리고 있나요?미국 빅스텝 베이비스텝 단행하면서 한국이 이 경향을 따라 금리를 올리고 있는 것으로 알고있다.Q4-2: 미국이 빅스텝과 베이비스텝을 단행하는 이유가 무엇이냐?미국의 높은 국가부채비율 때문이다. 그래서 돈을 찍어내야하고 이러한 요인이 반영되어 금리가 계속 오른다.Q4-3: 그렇다면 우리나라는 지속적으로 이러한 경향을 따라야 하는가?이러한 경향을 따르지 않은 대표적 예시가 있다. 옆 국가인 일본이다. 일본은 세계적 경향과 다르게 금리를 올리지 않겠다고 선언하였고, 현재 엔화 가치가 크게 떨어진 상태로 지속되고 있다. 이를 보아 우리나라도 국가경쟁력이 상당한 국가지만 여전히 미국의 금리변화 동향을 따라가야 한다고 생각한다."},{"q":"가천대학교 몇 지망인가? 솔직하게 말하셔도 된다.","a":"1지망이다 다른 학교 어디 쓴지까지 말할 수 있다. 진심이다. 작년도 11월 달에 완공된 국내 최초의 창업부인 가천대학교 코코네스쿨 시스템에 반했다. 이 지원제도 아래 가천대학교 대학 생활을 하고 싶다."},{"q":"마지막으로 할 말(10초 내)","a":"앞에 서 있는 동안 너무 심장이 빠르게 뛰어서 이게 그냥 떨림인지 설렘인지 모호했다. 이렇게 면접을 끝마치고 나서 보니 설렘이었던 것 같다. 지금도 설레고 가천대학교 입학을 하며 이 기분 다시 느껴보고 싶다 면접 들어주셔서 진심으로 감사하다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"경찰행정학과","jeonhyeong":"학생부종합(가천바람개비)","method":"생기부 기반 면접 / 면접시간 10분 / 면접위원 3명","notes":"","qa":[{"q":"2학년 진로활동에서 회복적 경찰활동에 대해서 발표했다고 하는데, 회복적 경찰활동이 무엇인가요?","a":"형사사법절차와 별개로 대화를 통해 피해자의 피해 회복과 가해자와 피해자의 관계 개선을 위한 활동입니다. 단순 처벌만으로는 피해 회복과 재발 방지 등 근본적인 문제가 해결되지 않아 당사자 간 대화로 관계 회복이 필요한 사건에 적합합니다."},{"q":"진행 단계는 어떻게 이루어져 있으며 실제 사례는 무엇이 있을까요?","a":"피해자와 가해자를 따로 면담 후 같이 만나서 갈등 원인과 해결 방안에 대해 자유롭게 대화합니다. 그 이후 모니터링을 통해 관계 회복과 약속 이행을 확인합니다. 실제 사례이자 빈번히 이루어지는 예로는 층간 소음이 있습니다."},{"q":"3학년 확률과 통계에서 강력 범죄 별 재범 시기를 비교했다고 하는데, 어떤 결과가 나왔나 그니까 범죄별 재범 시기에 차이가 있나?","a":"차이가 거의 없는 것으로 나왔습니다. 특정 시기 없이 수시로 발생한다는 결과가 나왔습니다. 이에 대해 추후 활동을 3학년 자율활동에서 진행했으며, 재범 방지를 위한 교정 시설의 문제점과 방향 등에 대해 탐구했습니다."},{"q":"1학년 행동 특성 및 종합의견에서 “자지 관리가 철저하여 지각, 조퇴, 결석이 단 한 번도 없이 개근하고”라고 쓰여 있는데 학생부 종합 전형에서 학생의 출결사항에 가산점을 줘야 한다는 의견에 찬성하는지 반대하는지 말해보세요.","a":"두 입장 모두 타당성을 가지고 있지만, 하나만 골라야 한다면 반대를 선택하겠습니다. 해당 학생의 상황을 모르고 단순히 지각과 결석에 적힌 숫자만을 보고 불이익을 주는 것을 옳지 않다고 생각합니다. 지각이나 결석 등이 있는 경우 한 번 정도는 그 이유를 들어볼 필요가 있다고 생각이 되기에, 서류에서 가산점을 주는 것이 아니라 면접에서 질의 후 가산점 또는 불이익을 주면 된다고 생각합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"금융수학과","jeonhyeong":"학생부종합(가천바람개비)","method":"면접시간 10분 / 면접위원 3명","notes":"대기실 들어가기 전에 건물 안에서 1층과 2층 줄을 서서 잠시 대기하는데 그때 화장실 가는 것이 좋음. · 일정 시간이 되어야 자신이 배정받은 시간에 건물 안으로 들어갈 수 있음. · 대기실에 들어가면 조용해서 나가는 것도 눈치 보이니까 물은 챙겨가는 것이 좋음.","qa":[{"q":"가천대 면접보러오시느라 수고하셨습니다. 괜찮으시면 면접시작할게요.","a":""},{"q":"지원동기","a":"안녕하세요. 저는 데이터분석에 관심~. Q2-1: 지원동기에서 데이터분석가를 희망하면 통계학과가 더 맞지 않을지.Q2-2: 컴퓨터랑 수학에 관심이 많은 것 같던데 그럼 컴퓨터 공학은..(대답하기전에 면접위원분이 수학에 대한 학습의지가 있는거죠? 하고 넘어가심)"},{"q":"가천대에 왜 오고싶은지Q3-1: 특히 어떤 과목을 배우고 싶은지","a":"1,2학년때에는 미적분학, 선형대수 등과 같은 수업을 듣고 3,4학년에는 금융공학, 금융IT프로그래밍과 같은 과목을 학습하고 싶습니다. (잘조사해왔네요)"},{"q":"데이터분석에 대해 구체화하여 생각해 본적 있는지","a":"기하시간에 탐구한 토폴로지분석을 은행에 접목하는 것 대답 (구체적으로 생각해본거 같네요 허허)Q4-1: 토폴로지 데이터분석이 뭘까요?데이터의 형태와 상호관계를 이해하고 분석하는 기술로~Q4-2: 생기부에 적혀있는 토폴로지 데이터분석 사례에 대해 말해보세요.어떤 한 영화사에서 ~"},{"q":"수학2 시간에 적분에 대한 조사했던데 이상적분과 구분구적법의 차이","a":"당시 정적분을 탐구하면서 르베그적분을 발견하였다고 말함.(그럼 르베그적분이 뭐냐고 물어보심, 르베그 정의 말하자 충분하다 하고 넘어감.)"},{"q":"물리학 논문 탐구에서 논문을 3편 읽었던데..","a":"대답. (논문 어디서 보냐시길래 학교에서는 디비피아를 제공해주어서 그곳에서 논문을 봤다고 말함)"},{"q":"원ㅇㅇㅇ어디에서의 싸인 코싸인","a":"(대답을 못했더니 기억이 나지 않나 보네요 라고 하셔서 네..기억이 잘 나지 않습니다.)Q7-1: 그럼 직각삼각형에서 싸인코사인을 설명해보세요(빗변이 생각이 안나고 어렵게 생각하다가 \"직각을 기준으로..\"하고 대답못함)"},{"q":"마지막으로 ‘수학으로 생각하기’라는 책을 읽고 가장 기억에 남는 것이 있다면","a":"대답"},{"q":"마무리하면서 꼭 하고 싶은말 있으면 해주세요.","a":"대답"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"반도체설계학과","jeonhyeong":"실기/실적위주(조기취업형계약학과)","method":"신분확인 → 대기실 입실 후 대기 → 앞사람 면접때 고사장앞에서 대기 → 면접 → 퇴실 / 면접시간 8분 / 면접위원 3명(1인 해당 회사 임원)","notes":"한 대기실에서 다른 과 친구들과 같이 대기 · 대기 시간 동안 자소서나 생기부, 책 볼 수 있고 전자기기는 사용 못 함. · 자기 서류에 전공과 관련해서 특이한 점이 있다면 꼭 답변을 철저히 준비해가면 좋을 거 같음. · 블라인드 면접이 아니고 고사장 안에서는 마스크를 벗김 · (추측)분위기로 보아 회사에 다니는 해당 학과 학생 한 명이 오신 것 같음 · (추측)교수님이 가운데 인사담당자가 양옆에 계심 · 밖에서 노크하면 마무리 하려하고 교수님께서 주로 질문을 많이 하시는 것 같음.","qa":[{"q":"자기소개 해보세요","a":"안녕하십니까, 변화에 순발력 있게 대처하고 반응하는 (이름)입니다.저는 1학년 때 반장을 했었습니다. 그 때 갑작스럽게 자율시간이 생겼습니다. 그 때 선생님께서 아이들의 생기부에 기재될 내용이 있도록 활동을 생각해보라 하셨습니다. 그 때 저는 토론을 추천 드렸고 선생님과 학생들 모두 좋은 평가를 해주셨습니다. 이런 능력이 세계 시장동향에 발빠르게 대처하는데에 도움 될 것 같습니다. 토론 중 4차 산업 혁명 이야기에서 반도체가 유망하다고 생각해 관심을 가지게 되었습니다. 이후 게임을 하며 설계에 흥미를 느꼈습니다. 이후 우연히 이 학과를 알게되었습니다 많은 기업들중에 원거리 무선 충전이 멋있다고 생각해서 지원하게 되었습니다."},{"q":"반도체 설계학과에 지원한 이유가 있나요?","a":"아까 말씀 드렸다시피 토론을 하며 관심을 가지게 되었고 이후 계산기를 설계해보며 관심을 가졌기 때문입니다."},{"q":"그러면 토론을 하지 않았다면 반도체를 좋아하지 않게 될 수도 있었겠네요?","a":"제가 게임을 통해 접하면서 흥미를 느끼기도 하였고 물리수업을 하면서도 느낀 것이라서 토론을 하지 않았어도 좋아했을 것 같습니다."},{"q":"OOO를 가지고 계산기를 만들었다고 했는데 어떻게 만들었어요? (원리가 뭐에요?)","a":"(얼버무림)OOO가 뭔지 모르는데 혹시 알려주실수 있을까요? (pnp반도체를 OOO이라고 부르잖아요? 그걸가지고 어떻게 계산기를 만들었죠?) 곱하기와 나누기는 안 되는 간단한 계산기 였습니다. 우선 10진법에서 2진법으로 숫자를 바꾸는 것부터 시작합니다. 전원이 켜진 것을 1, 꺼진 것을 0이라고 할 때 2 더하기 2를 예시로든다면 10과 10을 더합니다, 1과1이 더해지면 다음칸에 1을 표시하고 1과 0이면 해당 칸에 1을 0과 0을 더하면 해당칸에 0을 표시하는 방식으로 진행됩니다,"},{"q":"자신의 성격에 장점과 단점을 말해보세요,","a":"제가 생각하는 제장점은 친화력입니다, 리더활동을 하다보니 자연스럽게 친화력이 늘게 된 것 같습니다, 단점은 쉽게 기가 빨린다는 것입니다, 너무 활동적인 친구들 사이에 있으면 기가 빨리곤 합니다, (웃으시며 친화력이 좋은데 쉽게 기가 빨리면 안 되는데)"},{"q":"굳이 조기취업형계약학과에 지원한 이유가 뭔가요?","a":"첫 번째는 학업과 일을 병행함으로써 시너지가 발생한다는 점입니다. 두 번째는 일을 함으로써 돈을 벌어 학비를 충당할 수 있다는 점 때문에 지원했습니다."},{"q":"뭐 하나에 몰두해 본 적 있나요?","a":"아직까지 무언가에 잠을 줄여가면서까지 몰두해 본 적은 없습니다."},{"q":"마지막으로 하고 싶은 말이 있다면 10초정도 해보세요.","a":"이학과가 일과 학업을 병행해야하기 때문에 힘들다는것을 알고있습니다. 저는 각오하고 있습니다. 입학을 허락해주신다면 열심히 하겠습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"","jeonhyeong":"학생부종합(가천바람개비)","method":"대기, 면접실 앞 대기, 면접 / 면접시간 체감 9분 / 면접위원 3명","notes":"고사장 건물 들어가서 안내 따라 빈 강의실로 들어가서 자유롭게 종이보다보면 복도에서 같은 타임 사람들끼리 막 모으셔서 밑층으로 내려감 내려가다가 같은 학과끼리 분류하셔서 같은 방으로 넣으심(본인은 8명이었음) 여기서부터 폰 전원끄고 주의,안내 사항 듣고 번호표를 붙이라고 나누어주시는데 번호 순서대로 면접보게 됨 · 대기하면서 설명해주시는데 면접관님들이 답변 들으시다가 이해되시면 미리 끊을 수 있다고 친절히 설명해주심 · 면접대기실에서 설명들은건데 면접후기 면접끝나고 바로 인터넷같은 곳에 올리면 다른 경쟁자들이 그거 보고 본인들만 손해볼 수 있으니 면접 다 끝나고 후배들을 위해 나중에 면접후기 올리는게 좋겠다고 설명해주심 그러니 자기 면접 바로 전까지 인터넷(ex. ㅅㅁㅎ)에 면접후기가 왜 안올라오지.. 하면서 긴장하지 말것 · 면접관분들께서 3명이라 그런지 질문들어오는 속도와 그에 따른 압박감이 장난 아님 긴장하고 가는게 좋을듯 · 작년이나 재작년 면접 후기를 보면 긴장 풀어주시는 '오느라 힘들진 않았어요?ㅎㅎ' 질문같은거 꼭 하시고 면접 시작하셨다고 했는데 본인은 그런게 없어서 좀 당황함 · 왼쪽에 계시는 분은 엄청 인자하셨고 중간분은 인상쓰시고(본인이 느끼기에) 압박질문도 거의 하셨음 오른쪽에 계시는 분은 무표정 평범한 분이라 느꼈음 · 뭐가됐든 면접은 자신감이니 눈 똑바로 뜨고 무서운 분이라도 잘 눈 마주치면서 답하는게 좋을듯 차피 면접관님들 다음 질문 생각하시느라 반쯤은 책상보고 생기부 보고 계시니 그냥 냅다 쳐다보면서(주로 질문해주신 분 위로 답변할때 쳐다보기) 자신감있게 답변하기","qa":[{"q":"자기소개와 지원동기를 20초 내로 설명해보세요.","a":"안녕하세요. 저는 시간을 소중히 여기는 사람입니다. 그렇게 때문에 고등학교에서도 물리학, 미적분 같은 전공은 물론, 국어나 사회 같은 전공과 직접적인 관련이 없는 분야의 모든 배움을 헛되이 날리지 않고 집중했습니다. 그로 인해 더 넓은 시각을 가질 수 있었고 이것을 전공인 전자관련 분야에서도 활용하여 특정 사건을 이해하는데 있어 도움이 되었습니다. 또한 저는 오픈월드 탐험형 고사양 게임을 즐겨하는 취미가 있습니다. 이러한 게임을 위해 컴퓨터나 핸드폰의 성능에 대해서 더 잘 알아야할 필요성이 있었고 자연스레 반도체에 대한 관심이 돋아났습니다. 처음부터 RTX시리즈 같은 GPU, 즉 시스템 반도체를 알아보며 접했기 때문에 메모리 반도체보다는 시스템 반도체에 대해 더 관심을 가지게 되었고 이러한 반도체에 대해 더 전문적인 지식을 배우고 심화된 연구를 하여 반도체중에서도 특히 AP부분을 더 발전시켜보고싶다는 생각에 반도체.전자공학과를 희망하게 되었습니다. (20초 내로 하라고 하셨지만 최대한 어필하겠다고 생각하여 시간 생각안하고 그냥 답변함. 자기소개와 지원동기 각각 따로 준비했지만 그냥 즉석에서 중요해보이는 부분 뽑아서 잘 버무려서 답변드림)"},{"q":"졸업후에 최종진로가 뭐에요?","a":"앞에서 말씀드린대로 핸드폰이나 패드에 쓰이는 AP개발입니다."},{"q":"GPU와 CPU의 차이점에 대해 설명해보세요.","a":"(이때 메모리반도체와 시스템반도체로 잘못이해하고 설명하다가) 죄송합니다 다시 설명드리겠습니다. GPU는 간단한 일은 한번에 여러번 처리할 수 있으나 CPU는 복잡한 연산을 한번에 한가지씩 처리할 수 있습니다."},{"q":"캠공으로 고급물리학 들었네요..? 전기용량이 뭔지 설명해보세요","a":"전기용량은 축전기에서 얼마나 많은 전하를 저장할 수 있는지를 나타내는 것입니다."},{"q":"동아리 HCL..?HCL..? 염산 동아리? (동아리 이름 뜻을 궁금해하신듯 하셨음)","a":"(2학년때 한 화학동아리 이름에 학교이름이 일부 포함되어있어서 말씀드릴 수 없다고 하려 했는데 당황해서 바보같이 말끝을 흐려버림)아 그건 학교이름..(교수님이 아 그럼 말하면 안되지 하고 바로 끊으심)"},{"q":"그럼 HCL동아리에서 학생이 한 역할은 뭐에요?","a":"저는 화학 동아리 내에서도 생명과학 조의 조장을 맡아 여러 실험을 설계하고 진행하여 조를 이끌었습니다."},{"q":"어려운점은 없었어요?","a":"기존에 있던 실험을 새롭게 재구성하여 실험을 진행했기 때문에 조작변인과 통제변인을 새롭게 정하는 부분에서 어려움이 있었습니다."},{"q":"조원하고 어려운 점 같은건?","a":"아 실험을 재구성하다보니 이해하지 못하고 실험에 잘 참여하지 못하는 친구가 있었습니다. 조장으로서 조원의 참여를 독려해주기 위해 동아리 시간외 반으로 찾아가 실험 설명을 해주고 참여를 이끌어낸 적이 있습니다(면접관님들이 드디어 원하는 답변을 들었다는 듯이 으음 하심)"},{"q":"벡터가 왜 자연의 힘의 균형을 설명하는 훌륭한 도구죠? (생기부에 적힌 그대로 질문하심)","a":"당황하다가 생기부에 적혀있는 대로 물방울의 표면장력 이야기함"},{"q":"알짜힘을 벡터로 설명할 수 있어요?","a":"나무토막 생각하면서 힘과 반대방향, 상쇄 이야기를 횡설수설 하니까 중간에 네 알겠습니다 하고 끊으심"},{"q":"미적분 에세이에서 면저항 탐구했는데 여기서 적분을 어떻게 사용했죠?","a":"반도체 도핑과정을 거치면서 도핑은 모든 부분에 일정하게 이루어지는 것이 아니기 때문에 각각의 부분에 도핑이 얼마나 되어있는지 적분을 통해 확인한 다음 평균내어 면저항을 확인합니다."},{"q":"터널링현상을 제너항복과 연결지어 설명해보세요","a":"제너항복은 고동도로 도핑된 반도체에 역바이어스 전압을 걸게되면 에너지 밴드가 급격히 휘어지게 됩니다. 그렇게 되면 전자가 느끼는 공핍층의 두께가 줄어들어 전자가 일정한 확률로 원자가띠에서 전도띠로 넘어갑니다."},{"q":"왜 역전압을 걸면 에너지 밴드가 휘어지는지 알아요?","a":"(도핑을 고농도로 한 상태에서 역전압을 걸어주게 되면 P타입쪽에는 - 전압이 인가되어 에너지 밴드가 위쪽으로 올라라게 되고 N타입쪽에는 +전압이 인가되어 에너지 밴드가 내려가게 되어 에너지 밴드가 휘어지게 됩니다. 라고! 대답했어야 했는데 헷갈려서 그냥 답변 안하는게 낫다고 판단함) 잘 모르겠습니다!"},{"q":"마지막으로 하고싶은 말 있어요?","a":"저는 AP개발이라는 확실한 목표가 있는 사람입니다. 목표와 꿈을 가진 이상 그것을 성취하려 계속 노력할것이고 발전해나갈것입니다. 비록 지금은 부족해보일 수 있으나 졸업할때는 AP 연구개발 분야에서 연구를 시작하기에 충분히 준비된 사람이 되어있을거라 장담드릴 수 있습니다. 또한 오늘 면접에서 답변드리지 못한 부분은 입학 전까지 확실히 공부하고 복습해오겠습니다! (일어나서 나가기 전에) 오늘 면접 봐주셔서 감사합니다!"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"식품생명공학과","jeonhyeong":"학생부종합(가천바람개비)","method":"입실 → 주의사항 공지 → 대기 → 면접 → 퇴실 / 면접시간 7~8분 / 면접위원 3명","notes":"한 사람당 10분씩 진행한다고 공지했는데, 실제로는 7~8분 한 거 같음. · 시청각실같은 곳에서 다른 학과애들까지 다 같이 대기함. 면접은 방음 잘 되는? 방에서 따로 봄.","qa":[{"q":"지원동기","a":"건강에 관련된 생명과학에 관심이 많아 1학년때부터 다양한 분야에 대해 탐구하다가 자연스럽게 GMO식품에 접하게 되었다. 유전공학이 식품에 적용된 것에 대해 탐구하며, 유전공학 뿐만 아니라 다른 생명과학적인 개념들이 모두 식품과 접목될 수 있다는 점에 대해 알게되었고, 식품의 높은 활용도에 매력을 느끼게 되어서 지원하게 되었다고 대답함."},{"q":"가천대를 선택한 이유 / (+학과 사이트 읽어보고 관심분야 연구하는 교수님 계셨는지, 무슨분야인지)","a":"여러 식생공 학과 사이트 읽어보고, 가천이 유일하게 식품의 가공~유통 과정 뿐만 아니고 의약품이나 공정기술등 식품에 관련된 다양한 분야의 미래 인재 양성을 위해 노력하고 있는거 같아서 지원하게 되었다고 대답함. / 학과 사이트 읽어봤는데 자세히 기억이 안난다고 대답함"},{"q":"1학년 세특 ‘경우의 수를 통해 단백질이 만들어지는 과정’ 발표 내용 설명","a":"단백질이 아미노산으로 이루어져있고, 아미노산이 코돈으로 이루어져있는 개념을 사용하였다고 답변함 (말 끊고 뭐 또 물어보시길래 이어서 추가로 답변드려도 되냐고 여쭤봄.) 염기 4개를 이용하면 코돈이 64개가 나오는데 다양한 코돈이 중복되는 염기를 지정하기 때문에 20개로 경우의 수를 따짐. 펩타이드결합이 아미노산 5개로 이루어져있다고 가정했을 때만해도 20의 5승이라는 큰 수가 나오기 때문에, 경우의 수를 통해 단백질이 다양한 기능을 할 수 있는 이유-(잘 알고있는 거 같다고 대답 끊으심)"},{"q":"DNA추출실험에서 세제,에탄올 역할 설명","a":"세제는 계면활성제의 역할을 해서 세포막을 융해시켜줌. 에탄올은 DNA가 에탄올보다 용해도가 낮아서 위로 떠오를수 있게해주고, 에탄올이 물과 결합했을 때 나오는 나트륨이온이 DNA에 붙어서 응축을 도와준다고 다고 답변함."},{"q":"DNA전기영동실험 설명과 stacking gel 과 running gel 차이 설명 / (+running gel에서 일어나는 일에 대해 물어보심)","a":"농도가 높은 stacking gel에 시료를 일직선으로 세워 고정하고, 전류를 흘려주었을 때 running gel에서 시료가 이동하면 이동거리를 통해 분자 크기를 측정할 수 있다고함. DNA가 음전하기 때문에 +극쪽으로 이동하는 특성을 사용한다고 답변함./ (stacking gel보다 농도가 낮아서 시료가 잘 이동할 수 있다고 답변함.)"},{"q":"루미놀 반응 실험에서 인광과 발광 구분하는 법? 차이점?","a":"(물어보실지 모르고 한 번 정리만 해놨었던 내용이라 제대로 답변 못하고,인광이랑 발광 특징 바꿔서 답변함.)"},{"q":"GMO 약자가 뭔지?","a":"대답못함."},{"q":"마지막으로 하고싶은 말","a":"뽑아주세요! (하하하하하) 감사합니다~! (인사 후 퇴장)"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"심리학과","jeonhyeong":"학생부종합(가천바람개비)","method":"생기부 기반 면접 / 면접시간 10분 / 면접위원 2명","notes":"","qa":[{"q":"(지원동기 답변 후 꼬리 질문) 현재 대한민국 최저시급은 얼마인지 알고 있는가? (관련 생기부 활동을 확인하고) 최저시급 관련 문제 상황에 대해 어떻게 생각하는가?","a":"노무사의 꿈을 갖게 된 계기와 고등학교 생활을 통해 여러 가지 관련 진로활동을 했다는 내용을 포함해 지원동기를 이야기함. 따로 입학 후 학업계획을 묻는 질문은 없었음. 최저시급 9,620원이라고 답함. 선정 과정에서 노동자와 사측의 갈등이 발생할 수 있으며 이 과정에서 협의점을 찾아갈 수 있도록 돕는 노무사가 되고 싶다는 뜻을 밝힘. 이때 노동자 측의 입장과 사측의 입장 및 그에 대한 근거를 구체적으로 제시하였으며, 이러한 갈등의 원인이 객관적인 인상률 결정 체계가 없어서라는 점을 지적함. 따라서 이러한 체계의 수립이 필요하다는 생각을 밝힘."},{"q":"‘감정노동자’를 주제로 탐구활동을 했는데, ‘교사’도 감정노동자라고 생각하는가?","a":"3학년 진로 관련 탐구활동에서 ‘감정노동자’의 정의, 사람들의 잘못 알고 있는 점, 감정노동자가 업무상 겪는 어려움, 감정노동자로 여겨질 수 있는 직업의 범위 등을 설명함. 이를 토대로 사람과 상호작용하는 교사도 감정노동자에 속한다는 생각을 밝힘. 법에서 서비스직이라고 여겨지는 직종만 감정노동자로 본다는 점을 지적하며 교사도 마찬가지로 법률적인 보호를 받아야 한다는 점을 이야기함."},{"q":"법과 현실 간의 괴리가 발생하면 어떻게 할 것인가?","a":"순간적으로 ‘괴리’라는 단어의 의미가 기억이 나지 않았음. 그래서 ‘잠시 생각할 시간을 가져도 될까요?’라고 말하자 교수님들이 흔쾌히 시간을 가지라고 말하셔서 잠시 후에 답함. 법은 사람들이 공동체를 이루고 살아가기 위한 기본적인 규범과 틀이므로, 법을 지키는 것은 무엇보다 우선시 되어야 한다고 이야기함. 다만 현실에 법을 대입하여 문제가 발생했을 시, 이를 개정해가야 하는 방향으로 가야 한다고 답함."},{"q":"노무사가 되고자 하는데, 노무사가 되기 위한 과정을 알고 있는가? 알고 있다면 설명하시오.","a":"노무사 자격증을 취득해야 한다고 답함. 그리고 1단계 필기 시험은 객관식으로 과목에는 노동법, 사회보험법 등이 있으며 영어는 시험을 보거나 다른 시험 성적으로 대체가 가능하다고 이야기함. 2단계 시험에서는 노동법을 실제 문제 상황에 적용해보는 서술형 시험과 행정학, 경영학 등 여러 가지 과목 중에서 한 과목을 골라 서술형 시험을 봐야 한다고 답함. 또 마지막 단계로 면접에 응시해야 한다고 덧붙임."},{"q":"마지막으로 하고 싶은 말은?","a":"관심 분야를 진정으로 즐길 줄 알고, 끝까지 파고드는 성향임을 어필함. 또 가천대에 진학하여 학업뿐만 아니라 여러 경험을 쌓고 사람들과 교류하며 노무사로써 필요한 자질을 갖춘 사람으로 성장하겠다는 점을 이야기함. 이러한 역량을 꼭 가천대에서 키우고 싶다는 등의 멘트는 쑥스러워서 하지 못했음."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"심리학과","jeonhyeong":"학생부종합(가천바람개비)","method":"생기부 기반 면접 / 면접시간 10분 / 면접위원 2명","notes":"2:1로 진행하였는데 많은 면접 후기를 참고했지만 개인적으로 압박 면접이었음. 그러나 당황하지 않고 당당하게 말하는 자신감이 합격요인 중의 하나였음. · 생기부에 적혀있는 활동은 최대한 꼼꼼하게 다 답변할 수 있어야 함. · 자소서 관련 질문은 없었지만, 혹시 모르니까 여러 번 읽고 들어가기 · 꼬리 질문이 매우 많았음. · 중간에 답변이 끊기거나 준비한 내용을 다 전달하지 못하는 경우가 많으니 핵심만 두괄식으로 전달하는 연습이 필요함.","qa":[{"q":"자신의 장점이 드러나게 자기소개 해주세요.","a":"준비한 자기소개에다가 소통능력을 어필함. (본인의 과와 어울리는 장점 한 가지 이상 꼭 생각해두기.)Q1-1: 장점이 뭐라고 했죠?맞춤형 소통을 잘합니다!Q1-2: 어떻게 할수 있나요?청소년 아이들은 다양한 특성을 가지고 있습니다. 활발한 성격을 가진 아이에게는 제가 말을 많이 하기 보다는 경청의 자세로 들어주는 상담을 할 수 있습니다. 소심한 성격의 아이 같은 경우에는 스스로 선택하게 하는 상담을 이끌어가고 싶습니다. (이런 식으로 예를 들어서 장점을 보충설명함.)"},{"q":"자율동아리 이름의 뜻은?","a":"심량은 깊이 헤아리다 라는 뜻으로 내담자의 상황과 감정을 잘 헤아리자는 취지에서 동아리 이름을 정하였습니다.Q2-1: 생기부에 자세히 적혀 있지 않은데 무슨 활동을 했죠?상담사와 내담자의 역할을 돌아가면서 경험하는 활동을 했습니다. Q2-2: 전문 지식이 없어서 힘들었을텐데 어떻게 진행했나요?물론 상담 과정이 쉽지만은 않았습니다. 하지만 심리 용어도 찾아보고 책도 참고하면서 모의 상담을 했습니다. (가장 기억에 남는 활동을 언급하면서 어려움을 인정, 어떻게 극복했는지가 중요)"},{"q":"심리공부를 할 때 필요한 능력은 무엇이라고 생각합니까?","a":"분석력이라고 생각합니다.Q3-1: 왜 그렇게 생각합니까?사람의 마음은 눈에 보이지 않는 것이기 때문에 이를 과학적으로 접근해서 수치화하기 위해서는 통계와 분석력이 필요하다고 생각합니다."},{"q":"심리학 공부를 어떻게 했나요.","a":"주로 책과 기사를 활용했습니다. Q4-1: 어떤 책?청소년 상담 사례의 이해와 실제라는 책을 읽고 반항심리를 가진 아이들을 상담할 때 어떤 방식으로 대처해야 할지 많은 도움을 얻을 수 있었습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"외국어계열","jeonhyeong":"학생부종합(가천바람개비)","method":"면접 안내 → 대기 → 면접 진행 / 면접시간 오후 2시 50분~ / 면접위원 3명","notes":"자신감 !! (면접 대기하면서 물 마시기, 머리 식히기) · 마스크를 쓰고 면접을 진행했음","qa":[{"q":"지원동기 또는 자기소개 해보세요","a":"(준비했던 거 말함)"},{"q":"(한국사 생기부) 한비야 중국견문록을 읽고 가장 인상 깊은 점이나 흥미있던 점","a":"작가님이 중국 여행을 하며 한자에 대한 생각이 바뀐 것이 가장 인상 깊었습니다. 작가님은 원래 한자 사용에 중요성을 느끼지 못하였다고 합니다. 하지만 중국과 동아시아 국가들을 여행하며 한자를 아는 것이 얼마나 큰 힘이 되고 자신의 실속을 챙길 수 있는지 알게 되었다고 합니다."},{"q":"(3학년 동아리) ‘장자 인문학’ 책을 읽었는데 많은 사상가 중 장자를 선택한 이유","a":"도가를 주장한 장자는 현대인들에게 많은 교훈을 준다고 생각하기 때문입니다. 오늘날 사람들은 심각한 경쟁주의로 인해 자신의 이익을 추구하는 과정에서 과도한 경쟁이 발생합니다. 장자는 이익을 추구하는 것은 문제가 되지 않지만 추구하는 과정에서 탐욕 때문에 문제가 생긴다고 말합니다. 또한 자신의 내면을 가꾸기보다 외양만 가꾸는 현대인들에게도 교훈을 줍니다. 장자는 이러한 현상이 껍데기에 불구하다며 자신이 무엇을 좋아하는지, 무엇을 원하는지 등 본질적인 질문을 함으로써 자신의 내면을 가꾸라는 교훈을 줍니다."},{"q":"(3학년 동아리) 동아리 활동 중 가장 기억에 남거나 주의 깊게 탐구한 것","a":"반중정서와 반일정서를 비교한 것이 가장 기억에 남습니다. 반일정서가 가장 고조되었던 2019년에는 일본 정부의 화이트리스트 제외로 인해 무역 분쟁이 발생하여 한일 관계가 심각해졌습니다. 하지만 현재 반중정서는 한 사건만으로 고조된 것이 아니라 코로나 19, 문화공정, 동북공정 ,중국인들의 에티켓 문제 등 복합적인 이유라는 차이가 있습니다. 또한 반일정서가 심할 때는 일본제품 불매운동이 일어났지만 현재 반중정서가 심한 상황에서는 불매운동이 안 일어난다는 차이가 있습니다."},{"q":"중국의 정치 경제에도 흥미가 있어 보이는데 최근의 중국 관련 뉴스를 본 것 있나요","a":"중국 시진핑 주석 3연임에 대한 뉴스를 보았습니다. 시진핑은 많은 전문가들의 의견을 빗나가 3연임을 성공하였습니다. 하지만 시진핑 주석의 3연임은 중국 경제에 걸림돌이 될 것이라고 합니다. 중국은 시진핑 체제가 장기간 지속되어 새로운 정책이 아닌 같은 정책이 고수되고 있습니다. 그리고 현재 코로나19 방역 실패, 실업률 문제 등으로 시진핑과 공산당에 대한 불신이 높아졌습니다. 그래서 시진핑 주석의 장기 집권은 중국 경제의 걸림돌이 될 것이라고 합니다."},{"q":"(3학년 진로) 다문화사회에 대해 탐구한 거 같은데 이에 대해 설명해주세요","a":"현재 한국은 다문화 사회에 진입했다고 하지만 아직 미미한 수준이라고 생각합니다. 한국은 단일민족의식과 동질성이 강한 국가이기에 다른 나라의 문화를 적극적으로 접하는데 소극적입니다. 또한 한국인들은 인종차별에 대한 의식도 부족하여 다문화사회로서 아직 한계점이 많은 상황입니다. 그래서 저는 한국이 ‘김치없는 김치전’ 다문화 전력울 취해야한다고 생각합니다. 한국 문화가 타문화에 비해 높은 우위에 있는 것이 아닌 한국문화를 배경으로 타문화와 조화롭게 공존해야합니다."},{"q":"마지막으로 하고 싶은 말 있나요?","a":"도광양회의 의미는 자신의 재능과 능력을 과시하는 것이 아닌 참고 기다린다는 의미입니다. 도광양회의 의미를 인생에 적용하여 남들이 쟤 능력과 노력을 알아봐주지 못하여도 과시하는 것이 아니라 참고 기다린다면 언젠가 인정받을 것이라고 생각합니다."},{"q":"(꼬리질문) 도광양회를 사용한 중국 정치가가 있는데 혹시 아시나요?","a":"덩샤오핑이 사용한 것으로 알고 있습니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"외국어계열","jeonhyeong":"학생부교과(지역균형)","method":"신분 확인 → 대기실 입실 후 대기 → 조교 설명 → 면접 → 퇴실 / 면접시간 10분 / 면접위원 3명","notes":"한 대기실에서 같은 과 친구들과 같이 대기 (한 타임당 8명이었기에 대기실에도 8명이 같이 있었음) · 대기시간동안 자소서나 생기부, 책 볼 수 있고 전자기기는 사용 못함. (휴대폰은 끈 상태로 본인 소지) · 생기부 기반 면접이라고 나와있으나, 세세한 세특 내용까지 물어보지 않았고, 내가 한 답변에 대한 꼬리질문 형식으로 이어졌다. 본인이 지원하는 학과와 생기부 내용이 맞지 않더라도 왜 이 학과에 지원하고자 하는지만 잘 엮어 말하면 될 거 같다.","qa":[{"q":"안녕하세요, 가천대 외국어 계열 지원하신 거 맞죠?","a":"네 맞습니다!"},{"q":"답변이 길어지다보면 중간에 말을 끊을 수도 있어요. 그 점 감안하고 바로 면접 시작할게요","a":"네"},{"q":"본인 자기소개, 지원동기, 그리고 학업 계획 말씀해주세요","a":"네, 저는 평소 주변 사람들 뿐만 아니라 다른 반 친구들에게까지 다가가 인사를 건네는 성격입니다. 이러한 저의 모습을 보고 많은 사람들은 저에게 사교성이 좋다고 말해주었습니다. 저의 꿈은 시나리오 작가인데, 국경을 넘어 더 많은 사람들에게까지 저의 글을 알리기 위해선 다른 나라 사람들의 문화와 니즈를 파악할 필요가 있다고 생각하였습니다. 따라서 저는 세계의 문화권을 파악하고 (생각하다가 버벅거림) 궁극적으로는 영문으로 된 시나리오를 쓰는 것이 목표입니다."},{"q":"작가가 되고 싶다고 하셨는데, 작가라면 글을 제일 잘 쓰는 것이 중요하지 않아요? 본인이 글은 좀 쓴다고 생각하나요? (왜 굳이 여기 학과를 지원했냐는 뉘앙스였음)","a":"중학교와 고등학교 때 동아리에서 작가로 활동한 경험이 있습니다. 때문에 글을 쓰는 경험은 많이 해보기도 했고, 자신 있는 편이기 때문에 대학교에 와서는 다양한 문화권에 대해 알고 싶습니다."},{"q":"좋아하는 작가에 좋아하는 작품은 뭐예요?","a":"저는 봉준호 작가에 기생충이라는 작품을 인상깊게 봤습니다."},{"q":"해외적으로도 성공한 작품이죠. 그 영화의 어떤 부분이 사람들에게 인기를 끌었다고 생각해요?","a":"시나리오 적인 측면에서 분석해보자면, 보통 이전의 다른 많은 작품들은 부를 악으로, 가난을 선으로 표현했었지만 기생충의 경우 그와 반대로 부를 선으로 가난을 악으로 표현하였습니다. 이러한 내용은 사람들로 하여금 평소에는 말하고 싶었지만 차마 말할 수 없었던 부에 대한..(말하고 싶은 단어 생각 안 나서 계속 버벅거림)"},{"q":"부자들에 대한 열망? 이나 긍정적인 시각을 말하나요?","a":"어.. 네! 맞습니다"},{"q":"부를 선으로 표현하고 가난을 악으로 표현했다고 말한 부분이 재밌네요. 그럼, 다른 학교에도 이런 외국어 학과는 많은데, 왜 가천대를 굳이 지원했어요?","a":"지원하기 전 가천대의 커리큘럼을 보았습니다. 가천대의 경우 미디어와 문화번역, 영화로 읽는 영미문학 등 다양한 매체를 통해 영미권 문화를 파악할 수 있다는 점에서 제가 더 흥미롭고 능동적인 수업 참여가 가능할 거 같아 지원하게 되었습니다."},{"q":"지원하고자 하는 학과가 영미과라는 거죠?","a":"네 맞습니다."},{"q":"2학년 진로활동에서 “하기 싫어도 해라. 감정은 사라지고 결과는 남는다” 라는 말을 찾아 활동했다고 하는데, 무슨 활동이었는지 말해줄래요?","a":"자신의 좌우명을 찾고 발표하는 활동이었습니다. 저의 단점은 끈기가 부족한 것입니다. 초심보다 뒷심이 부족하여 일이 흐지부지 됐던 경험이 많은데, 이는 제가 그 일을 왜 해야만 하는지 명확한 동기를 찾지 못 해서라고 생각합니다. 따라서 앞으로는 명확한 동기를 찾아 원하는 결과를 성취하고자 노력하기 위해 저 말을 좌우명으로 삼았습니다."},{"q":"아까 동아리에서 작가로 활동한 경험이 있다고 했는데, 무슨 내용으로 했는지 말해줄래요?","a":"중학생 때 연극부 동아리에서 시나리오 작가로 활동했습니다. 당시 사회적으로 이슈가 됐던, 아이돌을 직접 뽑는 프로그램의 비리 사건을 각색하여 친구들에게 알려주었습니다."},{"q":"작가에게 가장 필요한 역량이 뭐라고 생각해요? (대답 못 하고 생각하고 있었음) 뭐.. 끈기라든가 그런 역량있잖아요","a":"아무래도 작가라는 직업은 정해진 일을 수행하는 것이 아닌, 혼자서 일을 찾아 해야하는 프리랜서 이다보니 쉽게 나태해질 수 있다고 생각합니다. 따라서 교수님이 말씀해주신 것처럼, 일을 끝까지 하고자 하는 끈기와 의지가 가장 필요하다고 생각합니다."},{"q":"(조교가 밖에서 문 두드림) 이제 시간이 다 되었는데, 마지막으로 하고 싶은 말 있을까요?","a":"글로벌한 가천대학교에서 배우는 외국어는, 단순히 그 나라의 문화와 언어 뿐만 아니라 미디어, 인문학, 출판 등 다양한 시선으로까지 저의 시선을 넓힐 수 있다고 생각하기 때문에, 꼭 가천대 교수님들께 수업을 들으며 글로벌한 사람으로 거듭나고 싶습니다. 1순위 대학인만큼, 뽑아주신다면 가천대에 저의 청춘을 바치겠습니다. 감사합니다!"}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"유아교육과","jeonhyeong":"학생부교과(지역균형)","method":"대기실 입실 → 신분 확인 후 대기 → 면접 → 퇴실 / 면접시간 10분 / 면접위원 3명","notes":"한 대기실에서 다른 과 친구들과 같이 대기 · 대기시간 동안 종이나 서류는 볼 수 있고 전자기기는 끄도록 안내함. · 떨지 않고, 암기하지 않고, 질문에 유연하게 답할 수 있도록 연습하는게 중요할 것 같음.","qa":[{"q":"가천대 유아교육과에 지원하게 된 계기가 무엇인가요?","a":"가천대 홈페이지에서 유아교육과 교육과정에 대해 찾아봤을 때 학교현장실습이 잘 구성되어있고 가천대학교의 비전과 제 가치관과도 비슷하여 지원하게 되었습니다."},{"q":"대학교 졸업 후의 계획은 어떻게 되나요?","a":"저는 유치원 교사가 되어 충분히 경력을 쌓은 후에 유치원 원장이 되고 저만의 유치원을 설립하는 것이 인생 최종 목표입니다."},{"q":"생기부를 보면 1학년 때 사립, 국공립 교사에 대한 기사를 작성했던데 어떤 활동을 했는지 자세히 설명해주세요.","a":"잠시 생각할 시간을 주시겠습니까?"},{"q":"사립, 국공립 교사가 되는 과정에 대한 차이점을 조사한 건가요?","a":"네, 차이점에 대해 조사했습니다."},{"q":"그럼 아까 자신의 유치원을 설립하고 싶다고 하셨는데 이는 사립 유치원 교사가 된다는 건가요?","a":"아뇨, 국공립 유치원에서 경력을 쌓고 나중에 유치원 설립에 대한 계획이 있습니다."},{"q":"생기부를 읽어봤는데, 이거 최근 대두되고 있는 문제 중에 하나죠. 3학년 때 영유아기 미디어 관련 전문 학술지를 탐구했다고 쓰여있는데 이에 대해 설명해주세요.","a":"먼저 제가 그 주제를 선정한 계기는 요즘 식당에 가면 모든 아이들이 스마트폰을 붙잡고 밥을 먹는 모습을 볼 수 있습니다. 그 모습을 보고 아이들에게 미디어가 어떤 영향을 끼치는 지에 대해 조사해보고 싶어 그 주제를 선정하게 되었습니다. 스마트폰이나 전자기기는 아이들의 시력을 저하시킬 뿐만 아니라 소근육 발달 또한 지체되게 합니다. 유아는 많은 교구 놀이를 통해 성장해야합니다. 유아는 함께 놀이하는 사람을 친구로 받아들이기 때문에 부모나 교사도 아이들과 친구가 될 수 있고, 함께 상호작용하며 말과 감정을 배우도록 해야합니다."},{"q":"3학년 때 동아리 3인조티칭 수업시연에서 본인이 한 역할과 수업을 준비하거나 진행하는 과정에서 겪은 어려움은 무엇이었는지 말해보세요.","a":"저희 모둠은 3명이서 팀을 이뤄 진행했는데 처음엔 소통이 잘 되지 않아 주제를 정하는 것부터 문제가 있었습니다. 제가 계속 조원 친구들에게 연락해서 분리수거 관련 환경 수업을 준비하자고 제안하였습니다. 수업을 준비하면서 가장 중요하게 생각했던 것은 아이들이 이해하기 쉬운 언어표현을 사용하는 것과 수업에 흥미를 잃지 않도록 모둠 활동을 하거나 동요를 활용하는 것이었습니다. 제가 모둠원 내에서 PPT 제작을 맡았는데 ‘지구에서 온 편지’를 소개하고 지구가 아파하는 모습을 강조하며 아이들이 쉽게 이해할 수 있도록 노력하였습니다.( 면접시간 10분 경과 노크 )"},{"q":"마지막으로 하고 싶은 말이나 답변 못 했던 질문 보충할 거","a":"오늘 제 이야기를 경청해주셔서 감사합니다. 오늘 면접관분들이 제 이야기를 경청해주셨던 것처럼 저도 미래에 아이들의 말에 귀를 기울이고 소통하는 유치원 교사가 되겠습니다. 충분한 전문성을 갖춘 교사가 되기 위해 가천대에서 교육을 통해 더욱 성장한 모습을 보여드리고 싶습니다. 감사합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"},{"univ":"가천대학교","dept":"응용통계학과","jeonhyeong":"학생부종합(가천바람개비)","method":"10분 내에서 면접관의 질문에 대한 답변을 하고, 종료 1분 전에 알려줌 / 면접시간 10분 / 면접위원 3명","notes":"답변에서 학과에 대한 강한 열망과 열정이 강하게 드러났던 것이 합격에 큰 도움이 되었던 것 같음. · 꼬리 질문이 많으므로 예상 질문 답변 내용에 대해 완벽하게 숙지해야 함. · 생활기록부 활동에 대한 꼬리 질문이 많았는데, 생활기록부에 작성된 내용을 꼼꼼히 살펴서 준비한다면 답변이 어렵지 않음.","qa":[{"q":"우리학과에 지원하게 된 동기에 대해서 말씀해주세요","a":"저는 외국의 통계를 이용한 마케팅 사례를 보고 통계에 마케팅으로 접목시켜 보고 싶다는 꿈이 있습니다. 따라서 통계학과에 진학한다면 제 꿈을 이룰 수 있을 것이라고 생각했습니다. 그중 가천대 응용통계학과의 인재상 중 사회현상에 대한 객관적 이해와 통찰력을 위한 전문 통계인이 있습니다. 이러한 모습이 제가 생각하는 통계학자의 모습이고 저는 항상 제가 배운 지식으로 남을 도울 수 있는 활동을 하고 싶었습니다. 가천대의 전공지식을 이용하여 지역 소상공인을 도와주는 캠페인이 제가 원하던 바로 그러한 프로젝트였기에 가천대에 진학하면 저의 통계에 대한 가치관을 더욱 키울 수 있을 것이라는 생각이 들어 지원하게 되었습니다."},{"q":"통계에서 검증과 반증이 필요하다고 했는데 이유가 뭔가요?","a":"통계학은 정확한 조사 자료를 바탕으로 해야 상관관계가 명확한 결괏값이 나오게 됩니다. 이 과정에서 조사자료에 오류가 발생한다면 조사 자료들 간의 상관관계에 모순이 발생할 수도 있어 자칫하면 조사 자료 전체의 신뢰성이 없어져 버리는 결과를 가져올 수도 있습니다. 따라서 조사 자료의 검증과 반증 과정을 통해 조사 자료의 신뢰성을 확보해야 결과에 오류가 발생하지 않습니다. 따라서 검증과 반증의 과정이 무조건 필요합니다."},{"q":"최저점을 미지수로 놓고 조건으로 주어진 수상인원수를 활용해 식을 구성하고 표준화를 통해 점수를 구했다고 했는데 어떤 방법인지 설명해주세요","a":"(예상하지 못했던 질문이라 당황하며)수상인원을 바탕으로 전체인원 수에서의 확률을 구해서 식을 구성하고 표준화를 통해 점수를 구할 수 있습니다.Q3-1: 그러면 그 과정에서 표준화는 어떻게 하나요?대답을 하지 못함.Q3-2: 그러면 정규 분포와 표준 분포의 차이점을 알고 있나요?정규분포는 각각의 확률과 편차가 제멋대로지만 표준 정규분포는 이것들을 일반화시켜 비교할 수 있다는 차이가 있습니다."},{"q":"알고리즘 편향에 대해 보고서를 작성했는데, 알고리즘 편향에 대해서 설명해보세요","a":"알고리즘 편향이란 사용자에게 맞춤화된 정보만을 제공해 다른 정보를 받아들이지 못하는 것입니다. 알고리즘이 자신의 관심사로만 구성되어 있으면 의견이 다른 다양한 정보를 얻을 수 없다는 문제점이 있습니다.Q4-1: 이를 해결하기 위해 필요한 노력이 있을까요?저는 알고리즘 편향을 해결하기 위해서 정부, 기업, 개인적 차원에서의 노력을 작성했습니다. 정부적 차원에서의 노력은 기업의 알고리즘이 투명성이 있는지 확인하고 이를 규제하는 법안을 만들어 기업의 알고리즘 투명성을 강화하는 노력이, 기업적 차원에서는 기업의 알고리즘을 소비자의 의견이나 외부평가를 통해 투명성을 확보하는 노력이 필요하고 개인적 차원에서는 정보를 비판적으로 받아들이며 편향된 정보만을 보지않기 위해 다양한 의견을 접하는 노력이 필요합니다."},{"q":"마지막으로 하고싶은 말 있으신가요?","a":"가천대에서 가천대의 가치관을 배우며 성장한다면 사회에 기여할 수 있는 통계학자가 될 수 있을 것이라고 생각합니다. 저도 나중에 사회에 기여할 수 있는 통계인이 되고싶습니다. 가천대에 진학하여 제 꿈을 이루어 보고 싶습니다. 감사합니다."}],"src":"세종특별자치시교육청 「보인다! 5.0 면접지도 길라잡이」","year":"2024학년도"}],"official":[{"category":"의사소통역량","jeonhyeong":"","q":"(인성관련) 교과부장으로 활동하며 학습 분위기를 조성하고, 스터디 그룹을 조직하여 중요한 역할을 수행했다고 기록되어 있습니다. 이 과정에서 친구들과 협력하며 공동체 속에서 어떤 역할을 했다고 생각하나요? 또한, 학습 과정에서 다른 친구들을 어떻게 도왔는지 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성","jeonhyeong":"","q":"(인성관련) 수업 시간에 주변 친구들에게 자신이 아는 바를 친절하게 알려주었다고 기록되어 있습니다. 친구들을 도울 때 어떤 점을 가장 중요하게 생각했으며, 이러한 경험이 본인에게 어떤 의미가 있었는지 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성","jeonhyeong":"","q":"(인성관련) 행동특성 및 종합의견에 친구들이 가장 본받고 싶은 학생으로 선정될 만큼 수업이나 생활 태도에서 귀감이 되었다고 기록되어 있습니다. 어떤 노력을 했기에 이런 평가를 받았다고 생각하나요? 또한, 본인이 보여준 태도가 학급 분위기에 어떤 영향을 주었다고 생각하는지 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성","jeonhyeong":"","q":"(인성관련) 행동 특성 및 종합의견에 결석한 친구의 역할을 자발적으로 대신하는 등 배려심을 보였다고 하는데, 이러한 행동을 실천하게 된 계기는 무엇이었으며, 이를 통해 공동체 속에서 본인이 맡은 역할을 어떻게 수행했다고 생각하나요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성","jeonhyeong":"","q":"(사회과학계열) 학우들과 경제 관련 지식을 공유하며 다양한 예시와 이론을 설명하는 모습을 보였다고 기록되어 있습니다. 기억나는 사례를 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성","jeonhyeong":"","q":"(사회과학계열) 경제 시간에 '외부 효과와 시장 실패' 개념에 관심을 가지고 공부했다고 기록되어 있습니다. 외부 효과의 개념을 설명하고, 외부 효과가 존재할 때 시장이 효율적으로 작동하지 않는 이유를 알려주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성","jeonhyeong":"","q":"(사회과학계열) 국어 시간에 언론 매체와 관련된 법을 주제로 카드뉴스를 제작하여 발표했다고 기록되어 있습니다. 해당 카드뉴스의 주요 내용을 설명하고, 제작 과정에서 매체의 특성을 어떻게 활용했는지 구체적으로 이야기해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성","jeonhyeong":"","q":"(사회과학계열) 수학 시간에 모집단이 정규분포를 따른다는 가정을 이해하고 이를 탐구했다고 기록되어 있습니다. 정규분포가 무엇인지 쉽게 설명하고, 왜 통계에서 정규분포를 따른다고 가정하는지 이야기해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"진학의지 및 계열적합성","jeonhyeong":"","q":"(사회과학계열) 사회 시간이 형벌 분야에 관심이 많아 스스로 관련 분야에 대한 심화 탐구를 진행했다고 기록되어 있습니다. 탐구한 주요 내용을 설명해 주세요. 또한, 형사 절차에서 인권 보장을 위한 제도 중 가장 중요하다고 생각하는 제도를 하나 꼽고, 그 이유를 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"진학의지 및 계열적합성","jeonhyeong":"","q":"(인문계열) 영어에 대한 관심과 능력이 뛰어나고, 학습 모둠에서도 적극적으로 활동하며 친구들이 글을 더 잘 이해할 수 있도록 도왔다고 기록되어 있습니다. 영어 학습 모둠에서 맡았던 역할을 설명해 주세요. 또한, 영어로 된 글을 이해할 때 가장 중요한 점은 무엇이라고 생각하는지 이유와 함께 이야기해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"진학의지 및 계열적합성","jeonhyeong":"","q":"(인문계열) 국어 시간에 어느 나라의 문화적 특성을 분석한 책을 읽고, 그 나라의 문화를 이해하는 활동을 했다고 기록되어 있습니다. 이 책에서 가장 인상 깊었던 문화적 특성은 무엇이며, 그 이유를 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(인문계열) 사회 시간에 ‘인공지능 발전과 통역사’를 주제로 양적 연구를 수행했다고 기록되어 있습니다. 본인의 연구에서 어떤 방식으로 자료를 모으고 분석했는지 설명해 주세요. 또한, 양적 연구 방법을 사용하면서 어떤 점이 도움이 되었는지 이야기 해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(인문계열) 국어 교과 기록에 따르면, 문단별로 내용을 잘 요약하고 재구성하는 능력이 뛰어나며, 인문·철학에 관심이 많다고 되어 있습니다. 이러한 평가를 받게 된 이유를 본인의 경험이나 사례를 들어 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(인문계열) 윤리 시간에 저작권 보호와 관련된 철학적 입장을 탐구했다고 기록되어 있습니다. 탐구한 핵심 내용을 간단히 설명해 주세요. 또한, 벤담의 공리주의적 관점과 칸트의 의무론적 관점은 어떻게 다른지 비교하고, 본인은 어떤 입장에 더 공감하는지 이유와 함께 이야기해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(자연계열) 수학 시간에 미적분과 관련된 책을 읽고, 미분과 적분에 대한 개념을 정리했다고 기록되어 있습니다. 책에서 인상 깊었던 핵심 내용을 설명하고, 미분의 정의를 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(자연계열) 물리 시간에 운동량 보존 실험, 전자가 유도 실험, 광전 효과 실험 등을 진행했다고 기록되어 있습니다. 이 중 가장 의미 있었던 실험은 무엇이며, 그 이유를 설명해 주세요. 또한, 전자기 유도 법칙이 무엇인지 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(자연계열) 화학 시간에 화학 결합을 학습한 후, 공유 결합에 관심을 가지고 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 설명해 주세요. 또한, 공유 결합, 이온 결합, 금속 결합의 차이를 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(자연계열) 생명과학 시간에 호르몬과 항상성을 학습한 후, 당뇨병 치료제에 대해 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 설명해 주세요. 또한, 혈당량 조절 과정의 핵심을 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(자연계열) 동아리 시간에 책을 읽고 실험을 제안하고 진행했다고 기록되어 있습니다. 실험을 제안한 이유가 무엇인지 설명해 주세요. 또한, 이 실험에서 본인은 어떤 역할을 맡았으며, 실험을 준비하는 과정에서 어떤 점을 고려했는지 이야기해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(공학계열) 과학 교과에 대한 지적 호기심이 강하고, 과학 지식을 적용하여 합리적으로 추론하는 능력이 뛰어나며, 자료를 분석하고 아이디어를 산출하는 능력이 우수하다고 기록되어 있습니다. 이러한 평가를 받게 된 이유를 본인의 경험이나 사례를 들어 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(공학계열) 물리 시간에 반도체의 정의와 원리에 대해 발표했다고 기록되어 있습니다. 반도체가 도체나 절연체와 구분되는 특징은 무엇인지 설명해 주세요. 또한, 에너지띠 구조를 기준으로 반도체, 도체, 절연체의 차이를 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(공학계열) 화학 시간에 화학 전지를 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 설명해 주세요. 또한, 화학 전지가 전기를 생성하는 원리는 무엇인가요? 산화환원 반응을 다른 사례를 들어 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(공학계열) 수학 시간에 함수의 극한과 연속을 배우고, 관련 문제를 해결했다고 기록되어 있습니다. 연속의 정의를 설명하고, 함수가 연속이면 항상 미분 가능하다고 할 수 있는지 그 이유와 함께 이야기해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(공학계열) 수학 시간에 자연상수 e에 대해 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 설명해 주세요. 또한, 자연상수 e의 정의를 설명하고, 미적분에서 자연상수가 중요한 이유를 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(간호보건계열) 화학 시간에 동위원소에 대해 관심을 가지고 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 간단히 설명해 주세요. 또한, 동위원소의 정의와 동위원소가 화학적 성질은 같지만 물리적 성질은 다른 이유를 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(간호보건계열) 자율활동에 학급의 건강 지킴이 역할을 맡아 체조 활동을 하고, 학생들의 참여를 유도했다고 기록되어 있습니다. 체조 활동에 친구들이 적극적으로 참여할 수 있도록 하기 위해 어떤 방식으로 설득하거나 독려했는지 설명해 주세요. 또한, 이 활동을 통해 건강과 운동의 중요성에 대해 새롭게 깨달은 점이 있는지요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(간호보건계열) 생명과학 시간에 신경계 단원에 대해 학습한 뒤 가장 큰 흥미를 보였고, 순환계 관련 질병을 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 간단히 설명해 주세요. 또한, 신경계가 순환계를 어떻게 조절하는지 교감 신경과 부교감 신경의 작용을 중심으로 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(간호보건계열) 화학 시간에 삼투현상과 삼투압을 정리하여 발표했다고 기록되어 있습니다. 발표 준비는 어떻게 했는지 설명해 주세요. 또한, 삼투현상과 삼투압의 정의를 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(간호보건계열) 과학 시간 기록에 따르면, 의문이 있으면 질문을 하면서 보다 심화된 내용을 찾아보는 등 과학적 탐구력과 문제해결력이 우수하다고 평가되었습니다. 이러한 능력을 발휘했던 사례를 들어 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(의약계열) 수업 시간에 의료 불평등을 해소하기 위한 노력의 필요성에 대해 이야기했다고 기록되어 있습니다. 핵심 내용을 설명해 주세요. 또한, 본인의 주장을 뒷받침하기 위해 어떤 근거를 제시했는지 이야기해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(의약계열) 화학 시간에 화학 평형에 대해 학습했다고 기록되어 있습니다. 가역 반응에서 정반응이 발열반응일 때, 온도를 조절하여 정반응을 유도하는 방법을 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(의약계열) 화학 시간에 화학 반응 속도와 온도의 관계에 대해 학습했다고 기록되어 있습니다. 화학 반응 속도는 온도와 어떤 관계가 있나요?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(의약계열) 생명과학 시간에 항상성과 질병의 관계에 대해 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 간단히 설명해 주세요. 또한, 물질대사의 조절에 관여하는 호르몬과 역할을 설명하고, 대사성 질환이 발생하는 원인을 물질대사 이상과 관련지어 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"(의약계열) 생명과학 시간에 방어 작용 수업을 듣고 항원-항체 반응과 호르몬-수용체 결합의 특이성에 대해 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 간단히 설명해 주세요. 항원-항체 반응의 특이성에 대해 설명하고, 인체의 특이적 방어 작용 중 중요하다고 생각하는 것을 설명해 주세요.","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"○○학과에 지원하였네요. ○○학과에 지원하게 된 동기가 된 고교 재학기간 중 활동이 있다면 무엇인가요?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"의사소통역량","jeonhyeong":"","q":"사회 교과 시간에 ‘저출산 지원정책의 문제점과 해결방안’을 주제로 조사해서 발표한 경험이 있네요. 발표 내용 중 기억에 남는 내용이 있으면 소개해 볼까요?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"전공적합성","jeonhyeong":"","q":"진로 선택 과목 선택할 때 고려했던 것과 과목 이수 후 도움이 되었던 점은?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성적 자질","jeonhyeong":"","q":"학생회에서 축제를 기획한 경험이 있는데, 어떤 역할을 맡아서 수행하였나요?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성적 자질","jeonhyeong":"","q":"역할 수행을 하다가 어려운 점은 어떻게 해결하였나요?","src":"경기도 진학 연구팀(진심) 「2026 면접을 준비하다」"},{"category":"인성","jeonhyeong":"","q":"자율활동에 부반장으로 활동하며 특별한 역할의 필요성을 어필하고 직접 수행했다고 기록되어 있는데, 그 역할이 왜 필요하다고 생각했으며, 이를 어떻게 수행했는지 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"인성","jeonhyeong":"","q":"교과부장으로 활동하며 학습 분위기를 조성하고, 스터디 그룹을 조직하여 중요한 역할을 수행했다고 기록되어 있습니다. 이 과정에서 친구들과 협력하며 공동체 속에서 어떤 역할을 했다고 생각하나요? 또한, 학습 과정에서 다른 친구들을 어떻게 도왔는지 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"인성","jeonhyeong":"","q":"수업 시간에 주변 친구들에게 자신이 아는 바를 친절하게 알려주었다고 기록되어 있습니다. 친구들을 도울 때 어떤 점을 가장 중요하게 생각했으며, 이러한 경험이 본인에게 어떤 의미가 있었는지 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"인성","jeonhyeong":"","q":"행동특성 및 종합의견에 결석한 친구의 역할을 자발적으로 대신하는 등 배려심을 보였다고 하는데, 이러한 활동을 실천하게 된 계기는 무엇이었으며, 이를 통해 공동체 속에서 본인이 맡은 역할을 어떻게 수행했다고 생각하나요?","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"사회과학계열","jeonhyeong":"","q":"학우들과 경제 관련 지식을 공유하며 다양한 예시와 이론을 설명하는 모습을 보였다고 기록되어 있습니다. 기억나는 사례를 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"사회과학계열","jeonhyeong":"","q":"경제 시간에 ‘외부효과와 시장실패’ 개념에 관심을 가지고 공부했다고 기록되어 있습니다. 외부 효과의 개념을 설명하고, 외부 효과가 존재할 때 시장이 효율적으로 작동하지 않는 이유를 알려주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"사회과학계열","jeonhyeong":"","q":"수학시간에 모집단이 정규분포를 따른다는 가정을 이해하고 이를 탐구했다고 기록되어 있습니다. 정규 분포가 무엇인지 쉽게 설명하고, 왜 통계에서 정규분포를 따른다고 가정하는지 이야기해 주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"사회과학계열","jeonhyeong":"","q":"사회 시간에 형법 분야에 관심이 많아 스스로 관련 분야에 대한 심화탐구를 진행했다고 기록되어 있습니다. 탐구한 주요 내용을 설명해주세요. 또한 형사 절차에서 인권 보장을 위한 제도 중 가장 중요하다고 생각하는 제도를 하나 꼽고, 그 이유를 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"인문계열","jeonhyeong":"","q":"영어에 대한 관심과 능력이 뛰어나고, 학습 모둠에서 적극적으로 활동하며 친구들이 글을 더 잘 이해할 수 있도록 도왔다고 기록되어 있습니다. 영어 학습 모둠에서 맡았던 역할을 설명해주세요. 또한, 영어로 된 글을 이해할 때 가장 중요한 점은 무엇이라고 생각하는지 이유와 함께 이야기해 주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"인문계열","jeonhyeong":"","q":"사회 시간에 ‘인공지능 발전과 통역사’를 주제로 양적 연구를 수행했다고 기록되어 있습니다. 본인의 연구에서 어떤 방식으로 자료를 모으고 분석했는지 설명해주세요. 또한, 양적 연구 방법을 사용하면서 어떤 점이 도움이 되었는지 이야기해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"인문계열","jeonhyeong":"","q":"국어 교과 기록에 따르면, 문단별로 내용을 잘 요약하고 재구성하는 능력이 뛰어나며, 인문, 철학에 관심이 많다고 되어 있습니다. 이러한 평가를 받게 된 이유를 본인의 경험이나 사례를 들어 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"자연계열","jeonhyeong":"","q":"수학 시간에 미적분과 관련된 책을 읽고, 미분과 적분에 대한 개념을 정리했다고 기록되어 있습니다. 책에서 인상 깊었던 핵심 내용을 설명하고, 미분의 정의를 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"자연계열","jeonhyeong":"","q":"물리 시간에 운동량 보존 실험, 전자기 유도 실험, 광전 효과 실험 등을 진행했다고 기록되어 있습니다. 이 중 가장 의미 있었던 실험은 무엇이며, 그 이유를 설명해주세요. 또한 전자기 유도 법칙이 무엇인지 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"자연계열","jeonhyeong":"","q":"생명과학 시간에 호르몬과 항상성을 학습한 후, 당뇨병 치료제에 대해 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 설명해주세요. 또한, 혈당량 조절 과정의 핵심을 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"자연계열","jeonhyeong":"","q":"동아리 시간에 책을 읽고 실험을 제안하고 진행했다고 기록되어 있습니다. 실험을 제안한 이유가 무엇인지 설명해주세요. 또한, 이 실험에서 본인은 어떤 역할을 맡았으며, 실험을 준비하는 과정에서 어떤 점을 고려했는지 이야기해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"공학계열","jeonhyeong":"","q":"과학 교과에 대한 지적 호기심이 강하고, 과학 지식을 적용하여 합리적으로 추론하는 능력이 뛰어나며, 자료를 분석하고 아이디어를 산출하는 능력이 우수하다고 기록되어 있습니다. 이러한 평가를 받게 된 이유를 본인의 경험이나 사례를 들어 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"공학계열","jeonhyeong":"","q":"물리 시간에 반도체의 정의와 원리에 대해 발표했다고 기록되어 있습니다. 반도체가 도체나 절연체와 구분되는 특징은 무엇인지 설명해주세요. 또한, 에너지띠 구조를 기준으로 반도체, 도체, 절연체의 차이를 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"공학계열","jeonhyeong":"","q":"수학 시간에 함수의 극한과 연속을 배우고, 관련 문제를 해결했다고 기록되어 있습니다. 연속의 정의를 설명하고, 함수가 연속이며 항상 미분 가능하다고 할 수 있는지 그 이유와 함께 이야기해 주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"간호보건계열","jeonhyeong":"","q":"화학 시간에 동위원소에 대해 관심을 가지고 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 간단히 설명해주세요. 또한, 동위원소의 정의와 동위원소가 화학적 성질은 같지만 물리적 성질이 다른 이유를 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"간호보건계열","jeonhyeong":"","q":"자율활동에 학급의 건강 지킴이 역할을 맡아 체조 활동을 하고, 학생들의 참여를 유도했다고 기록되어 있습니다. 체조 활동에 친구들이 적극적으로 참여할 수 있도록 하기 위해 어떤 방식으로 설득하거나 독려했는지 설명해주세요. 또한, 이 활동을 통해 건강과 운동의 중요성에 대해 새롭게 깨달은 점이 있나요?","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"간호보건계열","jeonhyeong":"","q":"생명과학 시간에 순환계와 신경계에 대해 학습할 때 가장 큰 흥미를 보였고, 순환계 관련 질병을 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 간단히 설명해주세요. 또한 신경계가 순환계를 어떻게 조절하는지 교감 신경과 부교감 신경의 작용을 중심으로 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"의약계열","jeonhyeong":"","q":"수업 시간에 의료 불평등을 해소하기 위한 노력의 필요성에 대해 이야기했다고 기록되어 있습니다. 핵심 내용을 설명해주세요. 또한, 본인의 주장을 뒷받침하기 위해 어떤 근거를 제시했는지 이이기해 주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"의약계열","jeonhyeong":"","q":"화학 시간에 화학 평형에 대해 학습했다고 기록되어 있습니다. 가역 반응에서 정반응이 발열반응일 때, 온도를 조절하여 정반응을 유도하는 방법을 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"},{"category":"의약계열","jeonhyeong":"","q":"생명과학 시간에 방어 작용 수업을 듣고 항원, 항체 반응과 호르몬-수용체 결합의 특이성에 대해 탐구했다고 기록되어 있습니다. 탐구한 주요 내용을 간단히 설명해주세요. 항원-항체 반응의 특이성에 대해 설명하고, 인체의 특이적 방어 작용 중 중요하다고 생각하는 것을 설명해주세요.","src":"인천광역시교육청 「2026학년도 대입 구술면접자료집」"}]};
